                ['p', 'Il participe en 1983 à la fondation du Front populaire ivoirien et devient responsable de la sécurité du parti au début des années 1990. Il est alors le beau-frère de Simone Gbagbo.'],
                ['h2', 'Du MPCI au gouvernement'],
                ['p', 'Il se rallie au Mouvement patriotique de Côte d’Ivoire en 2002 et participe aux négociations des accords de Ouagadougou. Nommé ministre de la Solidarité et des Victimes de guerre en 2010, il est ensuite ministre des Eaux et Forêts de 2016 à 2017.'],
