                ['p', 'Mathieu Babaud Darret, né en 1950 à Treichville, est un homme politique ivoirien. Titulaire d’une maîtrise de droit des affaires et d’un diplôme d’inspecteur principal des télécommunications, il fait carrière à l’Office national des télécommunications puis à Côte d’Ivoire Telecom.'],
                ['h2', 'L’ingénieur des télécoms'],
                ['p', 'Il occupe successivement des fonctions de direction financière, de gestion du personnel et d’inspection au sein de l’opérateur national, avant de rejoindre l’administration comme conseiller technique au ministère de la Construction.'],
                ['h2', 'L’entrée au gouvernement'],
                ['p', 'Membre du RHDP, il entre dans le gouvernement le 1er juin 2011 comme ministre des Anciens combattants et des Victimes de guerre.'],
            ],
