            'blocks' => [
                ['p', 'Nicolas Yssouf Djibo, né le 16 août 1949 à Bouaké, est un homme d’affaires et homme politique ivoirien. Fils du premier maire de Bouaké, Djibo Sounkalo, il étudie à la Sorbonne où il obtient une maîtrise en économétrie puis un diplôme d’études supérieures en gestion.'],
