                ['p', 'Emmanuel Esmel Essis, né le 5 octobre 1957 à Dabou, est un homme politique ivoirien. Diplômé de l’École supérieure de commerce d’Abidjan en 1983, il commence sa carrière chez Arthur Andersen avant de diriger Cosmivoire, puis l’usine Bonagui en Guinée de 2000 à 2008.'],
                ['h2', 'Le patron'],
                ['p', 'Il est directeur général régional du groupe ECCBC pour la Guinée, la Gambie et la Guinée-Bissau, puis directeur général du Centre de promotion des investissements en Côte d’Ivoire (Cepici) d’octobre 2011 à septembre 2021.'],
                ['h2', 'Le gouvernement'],
                ['p', 'Il entre au gouvernement en juillet 2018 comme secrétaire d’État chargé de la Promotion de l’investissement privé, devient ministre en septembre 2019, puis ministre de la Promotion de l’investissement et du Développement du secteur privé le 6 avril 2021, jusqu’en 2022.'],
