            'blocks' => [
                ['p', 'Zémogo Fofana est un homme politique ivoirien. Il est député et maire de la ville de Boundiali, dans la région de la Bagoué, au nord du pays.'],
                ['h2', 'Le ministre de l’Enseignement supérieur'],
                ['p', 'De 2002 à 2005, il est ministre RDR de l’Enseignement supérieur dans les gouvernements Affi N’Guessan III et IV et Diarra II, sous la présidence de Laurent Gbagbo.'],
