            'death' => '2014',
            'deathPlace' => 'Abidjan',
            'occupations' => ['Universitaire', 'Homme politique'],
            'summary' => 'Universitaire et homme politique ivoirien (1927-2014), Joachim Bony a été le premier ministre de l’Éducation nationale de la Côte d’Ivoire indépendante.',
            'blocks' => [
                ['p', 'Joachim Bony, né le 12 décembre 1927 à Grand-Bassam et mort le 12 août 2014 à Abidjan, est un universitaire et homme politique ivoirien. Premier Ivoirien licencié ès lettres et titulaire d’un CAPES d’histoire, il est docteur d’État de l’université Paris 1 Panthéon-Sorbonne.'],
                ['h2', 'Le ministre de l’Éducation'],
                ['p', 'Il est nommé ministre de l’Éducation nationale le 30 avril 1959, puis ministre de l’Éducation nationale chargé de l’Enseignement technique, de la Jeunesse et des Sports dans le premier gouvernement de la Côte d’Ivoire indépendante, jusqu’au 13 janvier 1963. Il collabore avec Mathieu Ekra à l’hymne national, l’Abidjanaise.'],
                ['h2', 'L’historien et le chef spirituel'],
                ['p', 'Emprisonné en 1963 et libéré en 1966, il dirige l’Institut d’histoire, d’art et d’archéologie africains de 1969 à 1982, puis préside le conseil d’administration de la RTI en 1994. Député de Jacqueville à deux reprises et secrétaire général de la Fondation Félix Houphouët-Boigny, il est intronisé cinquième Yrumanin du peuple alladian en 2006.'],
            ],
            'bibliography' => [
                ['title' => 'Joachim Bony', 'publisher' => 'Wikipédia en français', 'year' => null, 'url' => 'https://fr.wikipedia.org/wiki/Joachim_Bony'],
            ],
        ],
        [
            'slug' => 'pascal-abinan-kouakou',
            'name' => 'Pascal Abinan Kouakou',
