            'summary' => 'Haut fonctionnaire et homme politique ivoirien, Pascal Abinan Kouakou a dirigé les impôts avant d’être ministre et ministre-gouverneur du district de la Comoé.',
            'blocks' => [
                ['p', 'Pascal Abinan Kouakou est un haut fonctionnaire et homme politique ivoirien, administrateur général des services financiers. Il occupe d’importantes fonctions aux impôts avant d’être nommé directeur général des impôts le 14 décembre 2010, poste qu’il quitte le 15 juin 2016.'],
                ['h2', 'Les ministères'],
                ['p', 'Il est nommé ministre de la Fonction publique et de la Modernisation de l’administration le 12 janvier 2016, reconduit le 11 janvier 2017, puis ministre de la Modernisation de l’Administration et de l’Innovation du Service public le 19 juillet 2017. Le 10 juillet 2018, il devient ministre de l’Emploi et de la Protection sociale.'],
                ['h2', 'Le district de la Comoé'],
                ['p', 'Depuis le 18 juin 2021, il est ministre-gouverneur du district de la Comoé. Investi par le RHDP, il préside le conseil régional de l’Indénié-Djuablin de 2013 à 2023 et ne se représente pas en 2023.'],
            ],
            'bibliography' => [
                ['title' => 'Pascal Abinan Kouakou', 'publisher' => 'Wikipédia en français', 'year' => null, 'url' => 'https://fr.wikipedia.org/wiki/Pascal_Abinan_Kouakou'],
