        [
            'slug' => 'felix-houphouet-boigny',
            'name' => 'Félix Houphouët-Boigny',
            'fullName' => 'Dia Houphouët',
            'birth' => '1905',
            'birthPlace' => 'N’Gokro (Yamoussoukro)',
            'death' => '1993',
            'deathPlace' => 'Yamoussoukro',
            'occupations' => ['Homme d’État', 'Médecin', 'Planteur'],
            'summary' => 'Premier président de la Côte d’Ivoire indépendante, de 1960 à 1993, Félix Houphouët-Boigny a dominé la vie politique du pays pendant trois décennies.',
            'blocks' => [
                ['p', 'Félix Houphouët-Boigny, né Dia Houphouët le 18 octobre 1905 à N’Gokro, le village qui a précédé Yamoussoukro, et mort le 7 décembre 1993 dans cette ville, est un homme d’État ivoirien. Chef traditionnel, médecin, planteur et dirigeant syndical, il est député français de 1945 à 1959, membre de gouvernements français de 1956 à 1961, président de l’Assemblée nationale ivoirienne de 1953 à 1959, maire d’Abidjan de 1956 à 1960 et Premier ministre de 1959 à 1960.'],
                ['h2', 'Le père de l’indépendance'],
                ['p', 'Président du Rassemblement démocratique africain (RDA) dès 1946, il porte au Parlement français l’abolition du travail forcé, adoptée en 1946. La Côte d’Ivoire devient indépendante le 7 août 1960 et il en devient le premier président de la République.'],
                ['p', 'Son régime s’appuie sur le PDCI, parti unique, et sur le développement de l’agriculture d’exportation, cacao et café en tête, qui nourrit l’expression de « miracle ivoirien ». La chute des cours des matières premières dans les années 1980 fragilise ce modèle et le pays entre dans une longue crise économique.'],
                ['h2', 'La succession'],
                ['p', 'Il meurt le 7 décembre 1993 à Yamoussoukro après trente-trois ans à la tête de l’État. Henri Konan Bédié, alors président de l’Assemblée nationale, lui succède.'],
            ],
