            'blocks' => [
                ['p', 'Henri Konan Bédié, surnommé « HKB », né le 5 mai 1934 à Daoukro et mort le 1er août 2023 à Abidjan, est un homme d’État ivoirien. Ministre de l’Économie et des Finances de 1966 à 1977, puis président de l’Assemblée nationale à partir de 1980, il devient chef de l’État à la mort de Félix Houphouët-Boigny, le 7 décembre 1993.'],
                ['h2', 'La présidence'],
