                ['h2', 'Le chef du PDCI'],
                ['p', 'Président du Parti démocratique de Côte d’Ivoire, il arrive troisième au premier tour de l’élection présidentielle de 2010, puis se rallie à Alassane Ouattara. Il rompt leur alliance en 2018 et renonce finalement à se présenter en 2020, jugeant illégal le troisième mandat du président sortant.'],
            ],
