            'blocks' => [
                ['p', 'Robert Guéï, né le 16 mars 1941 à Kabakouma, un village de la région de Man, et mort assassiné le 19 septembre 2002, est un général et homme d’État ivoirien, issu du peuple yacouba.'],
                ['h2', 'Le putsch de 1999'],
                ['p', 'Chef d’état-major des Forces armées de Côte d’Ivoire, il prend la tête du coup d’État du 24 décembre 1999 qui renverse le président Henri Konan Bédié, qui venait de le limoger. Il préside le Comité national de salut public, fait adopter une nouvelle Constitution en 2000 et devient président de la République.'],
                ['h2', 'La défaite et l’opposition'],
                ['p', 'À l’issue de l’élection présidentielle d’octobre 2000, il conteste sa défaite face à Laurent Gbagbo mais quitte finalement le pouvoir. Il fonde ensuite l’Union pour la démocratie et la paix en Côte d’Ivoire (UDPCI) et participe à une tentative de réconciliation nationale avant de critiquer le pouvoir en place.'],
            ],
