            'summary' => 'Président de la République de 2000 à 2011, Laurent Gbagbo a été l’opposant historique de Félix Houphouët-Boigny avant de fonder le FPI puis le PPA-CI.',
            'blocks' => [
                ['p', 'Laurent Gbagbo, né le 31 mai 1945 à Gagnoa, est un historien, écrivain et homme d’État ivoirien, président de la République du 26 octobre 2000 au 11 avril 2011. Fondateur du Front populaire ivoirien (FPI) avec son épouse Simone, il est un opposant historique à Félix Houphouët-Boigny.'],
                ['h2', 'La présidence'],
                ['p', 'Il est élu à la tête de l’État lors de l’élection présidentielle de 2000 face au président sortant Robert Guéï. Son mandat est marqué par la crise politico-militaire de 2002 et par un affrontement avec la France.'],
                ['h2', 'La crise de 2010-2011'],
                ['p', 'Donné battu par Alassane Ouattara par la Commission électorale indépendante à l’issue du scrutin de 2010, il refuse de quitter le pouvoir en s’appuyant sur les chiffres du Conseil constitutionnel. Arrêté par les forces d’Alassane Ouattara le 11 avril 2011, il est détenu à La Haye et acquitté par la Cour pénale internationale en 2019.'],
                ['p', 'Rentré en Côte d’Ivoire en 2021, il quitte le FPI et fonde le Parti des peuples africains – Côte d’Ivoire (PPA-CI). Sa candidature à l’élection présidentielle de 2025 est rejetée par le Conseil constitutionnel.'],
            ],
