                ['p', 'Alassane Dramane Ouattara, souvent désigné sous ses initiales « ADO », né le 1er janvier 1942 à Dimbokro, est un homme d’État ivoirien. Économiste formé au Fonds monétaire international, il est le premier à exercer la fonction de Premier ministre de Côte d’Ivoire, de 1990 à 1993.'],
                ['h2', 'Le RDR et l’élection de 2010'],
                ['p', 'Élu en 1999 à la tête du Rassemblement des républicains (RDR), il ne peut se présenter aux présidentielles de 1995 et 2000 en raison d’une clause d’« ivoirité » introduite dans le code électoral. Candidat en 2010, il est proclamé élu par la Commission électorale indépendante avec 54 % des suffrages.'],
                ['h2', 'La présidence'],
                ['p', 'Il exerce pleinement ses fonctions après l’arrestation de Laurent Gbagbo, le 11 avril 2011, et prend ses fonctions le 6 mai 2011. Réélu en 2015, puis en 2020 après le décès d’Amadou Gon Coulibaly, il est à nouveau réélu lors de l’élection présidentielle de 2025.'],
