            'blocks' => [
                ['p', 'Ernest Boka, né le 7 décembre 1928 à Azaguié et mort le 6 avril 1964 à Yamoussoukro, est un homme politique et diplomate ivoirien, d’ethnie abé. Après des études à Bingerville et à l’École normale de Katibougou, au Soudan français, il s’inscrit à la faculté de droit de Grenoble, où il obtient en 1954 son doctorat en droit, le premier décroché par un Ivoirien, ainsi que son diplôme d’avocat.'],
                ['h2', 'Du gouvernement à la Cour suprême'],
