            'summary' => 'Juriste et homme politique, Francis Wodié a fondé le PIT et présidé le Conseil constitutionnel de 2011 à 2015.',
            'blocks' => [
                ['p', 'Francis Romain Wodié, né le 25 février 1936 à Abidjan et mort le 3 juillet 2023 dans la même ville, est un juriste et homme politique ivoirien. Militant de la Fédération des étudiants d’Afrique noire en France, il est arrêté et expulsé vers la Côte d’Ivoire en 1961, puis emprisonné en 1962.'],
                ['h2', 'Le syndicaliste et le professeur'],
                ['p', 'Il commence à enseigner le droit en 1966. Dans les années 1970, il fonde le Syndicat national de la recherche et de l’enseignement supérieur (SYNARES), s’exile en Algérie en 1973, puis revient à Abidjan comme doyen de la faculté de droit. Membre fondateur de la Ligue ivoirienne des droits de l’homme, il préside la section ivoirienne d’Amnesty International de 1985 à 1989.'],
                ['h2', 'Le politique'],
                ['p', 'En 1990, il crée le Parti ivoirien des travailleurs (PIT) et est élu député de Cocody. Candidat à l’élection présidentielle de 1995, il recueille 3,56 % des voix, puis se présente en 2000 et en 2010. Le 25 juillet 2011, il est nommé président du Conseil constitutionnel par Alassane Ouattara, fonction dont il démissionne le 3 février 2015.'],
