                ['h2', 'Le parcours à la BCEAO'],
                ['p', 'Formé au Centre de formation de la BCEAO puis à l’Institut du Fonds monétaire international à Washington en 1979, il intègre la Banque centrale des États de l’Afrique de l’Ouest en 1975. Directeur national de la BCEAO pour la Côte d’Ivoire et gouverneur suppléant au FMI de 1991 à 1998, il en devient gouverneur de 2011 à 2022.'],
                ['h2', 'La vice-présidence'],
                ['p', 'Il est nommé vice-président de la République par Alassane Ouattara le 19 avril 2022 et entre en fonction le 20 avril 2022, devenant selon la Constitution le successeur constitutionnel du président.'],
