                ['p', 'Mariatou Koné, née le 25 septembre 1965 à Boundiali, est une femme politique ivoirienne, professeure d’anthropologie à l’université Félix-Houphouët-Boigny d’Abidjan-Cocody. Elle est la première d’une famille de huit enfants et fait ses études secondaires à Korhogo, Sassandra puis Man avant d’étudier la sociologie à l’université nationale de Côte d’Ivoire.'],
