            'blocks' => [
                ['p', 'Anne Désirée Ouloto, née le 20 avril 1966, est une femme politique ivoirienne membre du Rassemblement des républicains (RDR), originaire du département de Toulepleu, dans la région du Cavally. Titulaire d’un baccalauréat littéraire, elle abandonne des études de droit pendant la crise universitaire de 1990 et devient institutrice.'],
                ['h2', 'Une militante du RDR'],
                ['p', 'Elle rejoint le RDR dès sa création en 1994. Assistante juridique à l’Autorité nationale de régulation du secteur de l’électricité de 2000 à 2005, elle est ensuite chargée d’études puis chef de cabinet au ministère de l’Enseignement supérieur. Pendant la crise de 2010-2011, elle est porte-parole de la campagne d’Alassane Ouattara.'],
                ['h2', 'Les ministères'],
                ['p', 'En juin 2011, elle est nommée ministre de la Salubrité urbaine, puis chargée du ministère de la Solidarité, de la Famille, de la Femme et de l’Enfant en novembre 2012. Le 6 avril 2021, elle devient ministre de la Fonction publique et de la Modernisation de l’administration, reconduite dans le gouvernement de Robert Beugré Mambé le 17 octobre 2023.'],
