                ['p', 'Myss Belmonde Dogo, née en 1975 ou 1976 selon les sources, est une femme politique ivoirienne membre du Rassemblement des houphouëtistes pour la démocratie et la paix (RHDP), originaire de Galébré dans le département de Gagnoa. Titulaire d’un master 2 en import-export, elle commence sa carrière en 2001 dans la société de transit de Côte d’Ivoire (SOTRANCI).'],
                ['h2', 'De l’Assemblée au gouvernement'],
                ['p', 'Élue députée de Dignago-Galébré-Guibéroua en 2016 sous la bannière de l’Union pour la Côte d’Ivoire de Gnamien Konan, elle est la même année élue vice-présidente de l’Assemblée nationale, fonction qu’elle occupe jusqu’en 2019. En septembre 2019, elle entre au gouvernement comme secrétaire d’État chargée de l’Autonomisation des femmes.'],
                ['p', 'Réélue députée en mars 2021, elle est nommée le 6 avril 2021 ministre de la Solidarité et de la Lutte contre la Pauvreté.'],
