            'blocks' => [
                ['p', 'Massandjé Touré-Litsé, née le 8 août 1963, est une économiste et femme politique ivoirienne. Diplômée d’un master of business administration en finance internationale de l’université George Washington, elle commence sa carrière dans les finances internationales chez Citibank.'],
                ['h2', 'Le café-cacao et la CEDEAO'],
                ['p', 'Elle travaille à la Banque mondiale et occupe la présidence puis la direction générale du comité de gestion du Conseil du café-cacao de Côte d’Ivoire de 2012 à 2017. Elle est ensuite commissaire aux affaires économiques et à l’agriculture au sein de la Communauté économique des États de l’Afrique de l’Ouest (CEDEAO), succédant à l’ancien ministre Adama Koné.'],
                ['p', 'Elle a également été nommée administratrice à la Banque africaine de développement.'],
