            'summary' => 'Médecin et femme politique, Christine Adjobi a été ministre chargée de la lutte contre le sida de 2005 à 2010.',
            'blocks' => [
                ['p', 'Christine Nebout Adjobi, née le 24 juillet 1949 à Grand-Bassam, est une femme politique ivoirienne. Elle obtient son baccalauréat série D en juin 1971, puis un doctorat d’État en médecine en mars 1981.'],
                ['h2', 'La lutte contre le sida'],
                ['p', 'Elle est ministre chargée de la Lutte contre le SIDA de 2005 à 2010, dans les gouvernements Konan Banny I et II puis Soro I et II. Pendant la crise politico-militaire, elle mène des campagnes dans les zones assiégées auprès des populations déplacées et des forces armées nationales.'],
                ['p', 'D’août 2022 à mars 2023, elle est ministre déléguée auprès du ministre de la Solidarité, chargée de la lutte contre le sida.'],
            ],
