            'blocks' => [
                ['p', 'Hortense Aka-Anghui, née Dadié le 18 décembre 1933 à Agboville et morte le 30 septembre 2017, est une femme politique ivoirienne. Pharmacienne, elle est propriétaire d’une officine de 1961 à 2017.'],
                ['h2', 'Élue et ministre'],
                ['p', 'Députée de Port-Bouët de 1965 à 1990, elle en est vice-présidente de l’Assemblée nationale. Elle est ministre de la Promotion de la femme dans le gouvernement de Félix Houphouët-Boigny de 1986 à 1990 et présidente de l’Association des femmes ivoiriennes de 1984 à 1991.'],
                ['p', 'Maire de Port-Bouët de 1980 à 2017, elle détient le record de longévité à la tête d’une commune ivoirienne.'],
