            'summary' => 'Membre historique du FPI, Agnès Monnet a été la première femme maire d’Agou et secrétaire générale du parti de 2014 à 2019.',
            'blocks' => [
                ['p', 'Agnès Monnet, née en 1954, est une femme politique ivoirienne, membre historique du Front populaire ivoirien (FPI). Titulaire d’un doctorat de troisième cycle en lettres modernes, elle est maître-assistante à l’université Félix-Houphouët-Boigny d’Abidjan-Cocody.'],
                ['h2', 'La francophonie et la mairie'],
                ['p', 'Elle dirige l’Agence ivoirienne de la coopération francophone, devenue Commission nationale de la Francophonie, de 2003 à 2011. Première femme maire de la commune d’Agou, dans la région de La Mé, de 2000 à 2013, elle est réélue à ce poste en 2018.'],
                ['h2', 'Le secrétariat général du FPI'],
                ['p', 'En juillet 2014, elle remplace Laurent Akoun au secrétariat général du FPI conduit par Pascal Affi N’Guessan. Elle démissionne de ses fonctions de secrétaire générale et porte-parole en mars 2019. Elle est l’épouse du ministre Léon Emmanuel Monnet.'],
