            'blocks' => [
                ['p', 'Mariam Dao Gabala, née le 3 mars 1960, est une femme d’affaires, femme politique et militante des droits des femmes ivoirienne. Aînée d’une famille de vingt-deux enfants, elle est formée à l’École supérieure de commerce d’Abidjan puis à HEC Paris.'],
                ['h2', 'La finance et l’inclusion'],
                ['p', 'Elle fait carrière comme directrice financière d’une institution de formation de cadres africains, puis comme consultante pour le Bureau international du travail, la Banque africaine de développement, l’Organisation internationale du travail et la Banque mondiale. Elle préside plusieurs réseaux, dont Solidaridad et Stand Up Africa 2050, et s’engage pour l’inclusion financière des femmes et des personnes pauvres.'],
                ['h2', 'Le Sénat et le football'],
                ['p', 'Sénatrice de la République de Côte d’Ivoire, elle préside le Comité de normalisation de la Fédération ivoirienne de football (CONOR-FIF) du 14 janvier 2021 au 4 mai 2022.'],
