            'summary' => 'Sociologue et militante des droits humains, Pulchérie Gbalet est connue pour son opposition au troisième mandat d’Alassane Ouattara et pour le mouvement des gilets orange.',
            'blocks' => [
                ['p', 'Pulchérie Gbalet est une sociologue et militante ivoirienne engagée dans la défense des droits humains et la promotion de la justice sociale. Elle obtient son DEA en sciences sociales à l’université de Bouaké en 1991 et commence sa carrière au Bureau national d’études techniques et de développement (BNETD), avant de devenir dirigeante syndicale à la centrale Dignité.'],
                ['h2', 'L’engagement citoyen'],
                ['p', 'Après la crise post-électorale de 2010-2011, elle fonde Alternative citoyenne ivoirienne (ACI) en 2017, qui devient sa principale plateforme d’action. En 2019, elle crée le mouvement des gilets orange, inspiré des Gilets jaunes français, pour dénoncer la pauvreté, la corruption et les atteintes aux droits fondamentaux.'],
                ['h2', 'L’arrestation de 2020'],
                ['p', 'Lors de l’annonce du troisième mandat présidentiel d’Alassane Ouattara en août 2020, elle appelle à des manifestations pacifiques. Interpellée dans la nuit du 15 au 16 août 2020 et placée à la Maison d’arrêt et de correction d’Abidjan, elle est poursuivie pour perturbation de l’ordre public et incitation à la révolte. Son arrestation suscite un large soutien, notamment de Laurent Gbagbo et d’Henri Konan Bédié.'],
            ],
            'bibliography' => [
