            'blocks' => [
                ['p', 'Chantal Moussokoura Fanny est une femme politique et diplomate ivoirienne, ambassadrice plénipotentiaire de la République de Côte d’Ivoire. Diplômée en sciences politiques de l’université Laval, elle est aussi titulaire d’un DESS en communication et doctorante en science politique.'],
                ['h2', 'La diplomatie et les mandats locaux'],
                ['p', 'Elle commence sa carrière diplomatique en 2006 comme secrétaire adjointe des Affaires étrangères. En 2013, elle devient maire de Kaniasso et est réélue à ce poste en 2018, jusqu’aux élections municipales de septembre 2023. Elle est conseillère du président de l’Assemblée nationale Guillaume Soro jusqu’en avril 2018.'],
                ['h2', 'Le Sénat'],
                ['p', 'Sénatrice de la région du Folon, elle est nommée vice-présidente du Sénat chargée de la Diaspora et de la coopération internationale le 12 octobre 2021. Le 7 décembre 2021, elle est élue au secrétariat général du Bureau de l’association des femmes parlementaires de la CEDEAO (ECOFEPA).'],
