            'summary' => 'Femme d’affaires et députée, Véronique Aka préside l’Union des femmes du PDCI depuis 2015.',
            'blocks' => [
                ['p', 'Véronique Aka, née le 15 août 1959 à M’batto, dans la région du Moronou, est une femme politique et femme d’affaires ivoirienne. Fille de Lambert Aka Aka et de Joséphine Kassi Ama, elle est adoptée par Félix Houphouët-Boigny et est la veuve du ministre Denis Bra Kanon.'],
                ['h2', 'L’entrepreneuse'],
                ['p', 'Après des études de comptabilité et un brevet de technicien supérieur, elle est assistante de direction au contrôle financier, puis se lance en 1978 dans l’exploitation forestière avant d’intégrer l’immobilier. Elle fonde en 1989 la société Afrique Construction, dont elle devient présidente-directrice générale, puis la Sotrapim en 2004 et Uni France Ivoire en 2014.'],
                ['h2', 'La députée'],
                ['p', 'Elle est élue députée de la circonscription d’Anoumaba-Tiémélékro en 1995, puis de M’batto-Assahara aux élections législatives de février 2011. En 2006, elle devient présidente du Réseau des femmes ministres et parlementaires de Côte d’Ivoire (REFAMPCI) et, en 2015, présidente de l’Union des femmes du PDCI.'],
            ],
