            'summary' => 'Juriste et ancienne porte-parole des Forces nouvelles, Affoussiata Bamba-Lamine a été ministre de la Communication de 2012 à 2017.',
            'blocks' => [
                ['p', 'Affoussiata Bamba-Lamine, née le 23 juin 1970 à Abidjan, est une femme politique ivoirienne, fille de Moriféré Bamba, homme politique d’opposition proche de Laurent Gbagbo. Elle obtient ses diplômes de droit à l’université Robert Schuman de Strasbourg, un DESS de juriste international à l’université René Descartes de Paris et un doctorat en droit comparé et droit international privé de l’université de Nancy.'],
                ['h2', 'Des Forces nouvelles au gouvernement'],
                ['p', 'Sa carrière débute en 2000 comme conseillère juridique au ministère de la Communication. Pendant la crise politico-militaire de 2002, elle met ses compétences de juriste au service de la rébellion des Forces nouvelles, dont elle devient la porte-parole, après avoir été conseillère juridique, membre du directoire politique et directrice de cabinet du secrétaire général.'],
                ['p', 'Du 21 décembre 2012 au 9 janvier 2017, elle est ministre de la Communication et porte-parole du gouvernement. Le 23 juin 2021, poursuivie pour tentative de coup d’État avec Guillaume Soro et dix-huit autres personnes, elle est condamnée à vingt ans de prison.'],
            ],
            'bibliography' => [
