            'occupations' => ['Femme politique', 'Haut fonctionnaire'],
            'summary' => 'Jeanne Gervais est devenue en 1976 la première femme ministre de Côte d’Ivoire, chargée de la Condition féminine.',
            'blocks' => [
                ['p', 'Jeanne Gervais, née Jeanne Ahou Siefer-N’Dri le 6 juin 1922 à Grand-Bassam et morte le 9 décembre 2012 à Abidjan, est une femme politique ivoirienne. Fille d’un père d’origine française et d’une mère baoulé, elle est formée à l’école des jeunes filles de Rufisque puis à l’École normale supérieure de Saint-Cloud, et devient inspectrice de l’enseignement primaire.'],
                ['h2', 'La première femme ministre'],
                ['p', 'Elle participe à la marche des femmes sur Grand-Bassam du 22 au 24 décembre 1949 pour protester contre l’arrestation des dirigeants politiques par les autorités coloniales. Elle est l’une des trois premières femmes élues à l’Assemblée nationale de la Côte d’Ivoire indépendante et y siège de 1965 à 1980.'],
                ['p', 'En 1976, Félix Houphouët-Boigny la nomme ministre chargée de la Condition féminine, faisant de la Côte d’Ivoire l’un des premiers pays subsahariens à compter une femme au gouvernement ; elle exerce cette fonction jusqu’en 1983. Elle est aussi la première présidente de l’Association des femmes ivoiriennes et reste militante du PDCI jusqu’à sa mort.'],
            ],
            'bibliography' => [
                ['title' => 'Jeanne Gervais', 'publisher' => 'Wikipédia en français', 'year' => null, 'url' => 'https://fr.wikipedia.org/wiki/Jeanne_Gervais'],
