                ['p', 'Célestine Olibé Trazéré, née le 6 avril 1967 à Bouaké, est une femme politique ivoirienne, députée à l’Assemblée nationale. De père bété et de mère baoulé, elle suit des études de droit à l’université de Bouaké, où elle obtient une licence en droit privé en 1995 puis une maîtrise en droit des affaires en 1996.'],
                ['h2', 'L’administration et le parti'],
