            'fullName' => 'Jeanie Elisabeth Badjo Djékouri',
            'birth' => '1971',
            'birthPlace' => 'Lakota',
            'death' => null,
            'deathPlace' => null,
            'occupations' => ['Juriste', 'Femme politique'],
            'summary' => 'Juriste et universitaire, Elisabeth Badjo Djékouri a été ministre de la Fonction publique du gouvernement Aké N’Gbo en 2010-2011.',
            'blocks' => [
                ['p', 'Jeanie Elisabeth Badjo Djékouri, née Dagbo le 24 décembre 1971 à Lakota, est une femme politique ivoirienne. Juriste, elle obtient en 2003 un doctorat en droit public de l’université de Paris V avec une thèse sur la coopération décentralisée entre la France et la Côte d’Ivoire, et enseigne à l’université Félix-Houphouët-Boigny d’Abidjan-Cocody.'],
                ['h2', 'Ministre de la Fonction publique'],
                ['p', 'Pendant la crise gouvernementale de 2010-2011, elle est ministre de la Fonction publique du gouvernement d’Aké N’Gbo, du 5 décembre 2010 au 11 avril 2011.'],
                ['p', 'Membre de ce gouvernement, elle est soumise à des sanctions de l’Union européenne à partir du 11 janvier 2011 : elle ne peut pas entrer dans l’Union et ses fonds sont gelés. Elle s’exile après la crise.'],
            ],
            'bibliography' => [
                ['title' => 'Elisabeth Badjo Djékouri', 'publisher' => 'Wikipédia en français', 'year' => null, 'url' => 'https://fr.wikipedia.org/wiki/Elisabeth_Badjo_Dj%C3%A9kouri'],
            ],
