            'birth' => '1954',
            'birthPlace' => 'Treichville (Abidjan)',
            'death' => null,
            'deathPlace' => null,
            'occupations' => ['Médecin', 'Femme politique'],
            'summary' => 'Professeure agrégée de médecine, Thérèse Aya N’Dri Yoman a été ministre de la Santé en 2011-2012 et l’artisane des soins gratuits.',
            'blocks' => [
                ['p', 'Thérèse Aya N’Dri Yoman, née le 15 octobre 1954 à Treichville, est une professeure agrégée de médecine et femme politique ivoirienne. Elle est titulaire d’un doctorat d’État à la faculté de médecine de l’université d’Abidjan obtenu en 1983 et d’une maîtrise en sciences biologiques et humaines de l’université Claude-Bernard-Lyon-I.'],
                ['h2', 'La carrière médicale'],
                ['p', 'Reçue à l’agrégation de médecine en hépato-gastro-entérologie en 1992, elle devient professeure titulaire et chef de service du CHU de Yopougon. Doyenne de l’UFR des sciences médicales d’Abidjan de 1998 à 2004, elle est ensuite directrice générale de la Santé de 2006 à 2008.'],
                ['h2', 'La ministre de la Santé'],
                ['p', 'Elle est ministre de la Santé et de la lutte contre le sida de juin 2011 à novembre 2012 et joue un rôle central dans la politique de soins gratuits du premier gouvernement d’Alassane Ouattara. Conseillère spéciale à la présidence chargée de la Santé en décembre 2012, elle est nommée ambassadrice de Côte d’Ivoire au Congo-Brazzaville le 13 juillet 2016. Militante du PDCI, elle siège à son bureau politique en 2020.'],
            ],
            'bibliography' => [
                ['title' => 'Thérèse Aya N’Dri Yoman', 'publisher' => 'Wikipédia en français', 'year' => null, 'url' => 'https://fr.wikipedia.org/wiki/Th%C3%A9r%C3%A8se_Aya_N%27Dri_Yoman'],
            ],
