            'occupations' => ['Femme politique'],
            'summary' => 'Ancienne députée de Tiassalé élue en 2016, Boni Noëlle Ekponon est maire de Guéyo depuis septembre 2023.',
            'blocks' => [
                ['p', 'Boni Noëlle Ekponon, née Boni-Noëlle N’Guessan, est une femme politique ivoirienne, ancienne députée à l’Assemblée nationale et maire de la commune de Guéyo. Autodidacte, elle s’est engagée en politique sans formation scolaire poussée.'],
                ['h2', 'La députée et la maire'],
                ['p', 'Elle est élue députée de la communauté Agni Sanwi de Tiassalé en 2016 comme candidate indépendante, puis adhère au Rassemblement des houphouëtistes pour la démocratie et la paix (RHDP). Pendant la pandémie de Covid-19, elle offre des kits sanitaires aux ressortissants de sa communauté et, en 2020, une assistance aux enfants scolarisés de sa commune.'],
                ['p', 'En 2023, elle est élue conseillère communale, puis maire de Guéyo le 20 septembre 2023.'],
            ],
            'bibliography' => [
                ['title' => 'Boni Noëlle Ekponon', 'publisher' => 'Wikipédia en français', 'year' => null, 'url' => 'https://fr.wikipedia.org/wiki/Boni_No%C3%ABlle_Ekponon'],
            ],
