        [
            'slug' => 'marie-kore',
            'name' => 'Marie Koré',
            'fullName' => 'Zogbo Céza Galo Marie',
            'birth' => '1912',
            'birthPlace' => 'Gossa (Daloa)',
            'death' => '1953',
            'deathPlace' => null,
            'occupations' => ['Militante', 'Commerçante'],
            'summary' => 'Militante du PDCI-RDA, Marie Koré a conduit le groupe bété lors de la marche des femmes sur Grand-Bassam, en décembre 1949.',
            'blocks' => [
                ['p', 'Marie Koré, née Zogbo Céza Galo Marie en 1912 et morte en 1953, est une militante de l’indépendance et une entrepreneure ivoirienne. Originaire de Gossa, dans la sous-préfecture de Gboguhé, près de Daloa, elle s’installe en Basse-Côte et ouvre à Treichville un allocodrome, lieu de vente de bananes plantains frites où elle emploie des jeunes femmes de sa région.'],
                ['h2', 'La marche des femmes sur Grand-Bassam'],
                ['p', 'Membre du Rassemblement démocratique africain dirigé par Félix Houphouët-Boigny, elle est élue en 1947 présidente du comité féminin du PDCI à Treichville. Elle participe aux manifestations devant le palais du gouverneur Péchoux en 1949, puis à celles des 22, 23 et 24 décembre de la même année.'],
                ['p', 'Lors de la marche sur Grand-Bassam, elle est à la tête du groupe bété qui rejoint la ville à pied. Le 24 décembre, alors que les forces de l’ordre forment un barrage sur le pont de la lagune Ouladine, elle franchit le barrage avec sa fille sur le dos, glisse et tombe ; blessée et arrêtée, elle est condamnée à deux mois de prison. Le pont est rebaptisé pont de la Victoire en mémoire de la marche.'],
                ['p', 'Elle meurt en 1953, alors que sa fille a sept ans. Un billet de 1 000 francs CFA et un timbre postal à son effigie ont été créés, et une école primaire d’Adjamé ainsi que plusieurs associations féminines portent son nom.'],
            ],
            'bibliography' => [
                ['title' => 'Marie Koré', 'publisher' => 'Wikipédia en français', 'year' => null, 'url' => 'https://fr.wikipedia.org/wiki/Marie_Kor%C3%A9'],
            ],
        ],
        [
            'slug' => 'leopoldine-tiezan-coffie',
            'name' => 'Léopoldine Tiézan Coffie',
            'fullName' => 'Léopoldine Tiézan Coffie',
            'birth' => '1950',
