            'death' => '2026',
            'deathPlace' => 'Abidjan',
            'occupations' => ['Femme politique'],
            'summary' => 'Figure du PDCI-RDA, Léopoldine Tiézan Coffie a présidé son Union des femmes avant d’être ministre de la Famille et de la Promotion de la femme sous Henri Konan Bédié.',
            'blocks' => [
                ['p', 'Léopoldine Tiézan Coffie, née en 1950 et morte le 6 février 2026 à Abidjan des suites d’une crise cardiaque, est une femme politique ivoirienne membre du Parti démocratique de Côte d’Ivoire – Rassemblement démocratique africain (PDCI-RDA).'],
                ['h2', 'Du parti au gouvernement'],
                ['p', 'Dans les années 1990, elle préside l’Union des femmes du PDCI (UFPDCI). Sous la présidence d’Henri Konan Bédié, elle devient ministre de la Famille et de la Promotion de la femme.'],
                ['p', 'Elle siège ensuite au bureau politique du parti et en est la déléguée départementale à Daloa depuis 2013. Nommée vice-présidente du PDCI en novembre 2019, elle préside également le Réseau international des femmes pour des actions affirmatives (RIFAA).'],
            ],
            'bibliography' => [
                ['title' => 'Léopoldine Tiézan Coffie', 'publisher' => 'Wikipédia en français', 'year' => null, 'url' => 'https://fr.wikipedia.org/wiki/L%C3%A9opoldine_Ti%C3%A9zan_Coffie'],
            ],
        ],
        [
            'slug' => 'niale-kaba',
            'name' => 'Nialé Kaba',
            'fullName' => 'Nialé Kaba',
            'birth' => '1962',
            'birthPlace' => 'Bouko',
            'death' => null,
            'deathPlace' => null,
            'occupations' => ['Économiste', 'Femme politique'],
            'summary' => 'Ministre de l’Économie et du Plan depuis 2016, Nialé Kaba est devenue en janvier 2026 ministre d’État des Affaires étrangères.',
            'blocks' => [
                ['p', 'Nialé Kaba, née en 1962 à Bouko, est une femme politique ivoirienne. Après un baccalauréat série C en 1981 et une maîtrise en sciences économiques à l’université d’Abidjan-Cocody en 1989, elle obtient à Paris un diplôme d’ingénieur en statistiques économiques au Centre européen de formation des statisticiens économistes des pays en voie de développement et un diplôme d’études approfondies en économie internationale et économie du développement, puis se forme à la gestion de la politique économique à l’Institut du Fonds monétaire international en 1993.'],
                ['h2', 'Les finances, puis la diplomatie'],
                ['p', 'Elle enseigne la macroéconomie à l’École nationale supérieure de statistique et d’économie appliquée, puis occupe de 1991 à 2000 les fonctions de chargée d’études et de chef de cabinet du Premier ministre. Directrice générale de Côte d’Ivoire Tourisme de 2005 à 2007, elle entre au gouvernement en 2011 comme ministre de la Promotion du Logement.'],
                ['p', 'Ministre déléguée auprès du Premier ministre chargée de l’Économie et des Finances du 22 novembre 2012 au 12 janvier 2016, elle devient ministre du Plan et du Développement, puis ministre de l’Économie, du Plan et du Développement. Le 23 janvier 2026, elle est nommée ministre d’État, ministre des Affaires étrangères et de la Coopération internationale.'],
            ],
            'bibliography' => [
                ['title' => 'Nialé Kaba', 'publisher' => 'Wikipédia en français', 'year' => null, 'url' => 'https://fr.wikipedia.org/wiki/Nial%C3%A9_Kaba'],
            ],
