            'name' => 'Raymonde Goudou Coffie',
            'fullName' => 'Raymonde Michèle Goudou Coffie',
            'birth' => '1956',
            'birthPlace' => 'Abidjan',
            'death' => null,
            'deathPlace' => null,
            'occupations' => ['Pharmacienne', 'Femme politique'],
            'summary' => 'Pharmacienne de formation, Raymonde Goudou Coffie a été ministre de la Famille, puis de la Santé, avant de devenir ministre gouverneure du district des Lacs.',
            'blocks' => [
                ['p', 'Raymonde Michèle Goudou Coffie, née à Abidjan en 1956 d’un père originaire de la Guadeloupe et d’une mère ivoirienne, est une femme politique ivoirienne. Pharmacienne biologiste diplômée d’un doctorat en pharmacie de l’UER de pharmacie de Caen en 1984, elle dirige la pharmacie et le laboratoire du Centre hospitalier régional de Yamoussoukro avant d’exercer comme conseillère technique du ministre des Sports et des Loisirs de 2000 à 2002.'],
                ['h2', 'Du gouvernement au district des Lacs'],
                ['p', 'Militante du PDCI à partir de 2000, elle entre au bureau politique du parti cinq ans plus tard. Elle est ministre de la Famille, de la Femme et de l’Enfant de juin 2011 à novembre 2012 et porte-parole adjointe du gouvernement, puis ministre de la Santé et de l’Hygiène publique de 2012 à 2018.'],
                ['p', 'Elle dirige ensuite le ministère de la Modernisation de l’Administration et de l’Innovation du service public de juillet 2018 à mai 2020 et assure à partir de mars 2020 l’intérim du ministère de la Culture et de la Francophonie. Le 18 juin 2021, elle est nommée ministre gouverneure du district autonome des Lacs.'],
            ],
            'bibliography' => [
                ['title' => 'Raymonde Goudou Coffie', 'publisher' => 'Wikipédia en français', 'year' => null, 'url' => 'https://fr.wikipedia.org/wiki/Raymonde_Goudou_Coffie'],
            ],
