        [
            'slug' => 'ramata-ly-bakayoko',
            'name' => 'Ramata Ly-Bakayoko',
            'fullName' => 'Ramata Bakayoko-Ly',
            'birth' => '1955',
            'birthPlace' => 'Abidjan',
            'death' => null,
            'deathPlace' => null,
            'occupations' => ['Universitaire', 'Femme politique'],
            'summary' => 'Professeure d’odonto-stomatologie, Ramata Ly-Bakayoko a présidé l’université Félix-Houphouët-Boigny avant d’être ministre de l’Enseignement supérieur, puis de la Femme.',
            'blocks' => [
                ['p', 'Ramata Bakayoko-Ly, née le 29 juin 1955 à Abidjan, est une femme politique ivoirienne. Professeure titulaire des universités, agrégée d’odonto-stomatologie du CAMES en novembre 1990 et titularisée en 1994 en pédodontie-prévention, elle est l’auteure de 97 articles scientifiques et a encadré 47 thèses de doctorat en chirurgie dentaire.'],
                ['h2', 'L’université et les ministères'],
                ['p', 'Présidente de l’université Félix-Houphouët-Boigny de Cocody de 2011 à 2016, elle préside pendant six ans la commission régionale d’experts du bureau Afrique de l’Ouest de l’Agence universitaire de la Francophonie. Elle est nommée ministre de l’Enseignement supérieur et de la Recherche scientifique le 12 janvier 2016, fonction qu’elle exerce jusqu’au 4 juillet 2018.'],
                ['p', 'Elle devient ministre de la Femme, de la Famille et de l’Enfant le 10 juillet 2018, jusqu’en avril 2021, puis est nommée le 8 septembre 2021 ambassadrice et déléguée permanente de la Côte d’Ivoire auprès de l’UNESCO, avec résidence à Paris.'],
            ],
            'bibliography' => [
                ['title' => 'Ramata Ly-Bakayoko', 'publisher' => 'Wikipédia en français', 'year' => null, 'url' => 'https://fr.wikipedia.org/wiki/Ramata_Ly-Bakayoko'],
            ],
        ],
        [
            'slug' => 'euphrasie-kouassi-yao',
            'name' => 'Euphrasie Kouassi Yao',
            'fullName' => 'Euphrasie Kouassi Yao',
            'birth' => '1964',
            'birthPlace' => 'Bouaké',
            'death' => null,
            'deathPlace' => null,
            'occupations' => ['Enseignante', 'Femme politique'],
            'summary' => 'Titulaire de la chaire UNESCO « Eau, Femmes et Pouvoir de décisions », Euphrasie Kouassi Yao a été nommée ministre en janvier 2015 et conseillère spéciale chargée du genre.',
            'blocks' => [
                ['p', 'Euphrasie Kouassi Yao, née le 18 avril 1964 à Bouaké, est une femme politique ivoirienne. Après un baccalauréat scientifique en 1984 au lycée de jeunes filles de Yamoussoukro et un certificat d’aptitude professionnelle d’enseignement secondaire obtenu en 1989 à l’École normale supérieure d’Abidjan, elle enseigne l’histoire-géographie au lycée Sainte-Marie d’Abidjan, puis devient consultante en genre et développement pour les Nations unies, la Banque africaine de développement et la Banque mondiale.'],
                ['h2', 'Le genre comme mandat'],
                ['p', 'En 2006, elle devient titulaire de la chaire UNESCO « Eau, Femmes et Pouvoir de décisions » et dirige de mars 2006 à juillet 2011 la direction nationale de l’Égalité et de la Promotion du Genre. Elle est nommée ministre le 12 janvier 2015 et prend fonction le 15 janvier 2015.'],
                ['p', 'Conseillère spéciale du président Alassane Ouattara chargée du genre pendant sept ans, elle est depuis avril 2023 conseillère spéciale du Premier ministre pour les mêmes questions. Elle a publié trois livres entre 2022 et 2025.'],
            ],
            'bibliography' => [
                ['title' => 'Euphrasie Kouassi Yao', 'publisher' => 'Wikipédia en français', 'year' => null, 'url' => 'https://fr.wikipedia.org/wiki/Euphrasie_Kouassi_Yao'],
            ],
        ],
        [
            'slug' => 'nasseneba-toure-diane',
            'name' => 'Nasseneba Touré Diané',
            'fullName' => 'Nasseneba Touré Diané',
            'birth' => '1972',
            'birthPlace' => 'Korhogo',
            'death' => null,
            'deathPlace' => null,
            'occupations' => ['Femme politique'],
            'summary' => 'Première femme maire d’Odienné en 2013, Nasseneba Touré Diané est ministre de la Femme, de la Famille et de l’Enfant depuis avril 2021.',
            'blocks' => [
                ['p', 'Nasseneba Touré Diané, née le 24 septembre 1972 à Korhogo et originaire d’Odienné, est une femme politique ivoirienne. Partie étudier aux États-Unis à 19 ans, elle y obtient un diplôme d’ingénieure en NTIC et un bachelor de business international, puis travaille chez Comsat et au département transport et infrastructure de la Banque mondiale de 2003 à 2006.'],
                ['h2', 'Du RDR à la mairie d’Odienné'],
                ['p', 'Elle adhère au Rassemblement des républicains dès sa création en 1994 et anime le parti auprès de la diaspora aux États-Unis. De retour en Côte d’Ivoire, elle est conseillère technique au ministère des Nouvelles technologies de l’information et de la Communication en 2007, puis auprès du Premier ministre Guillaume Soro en 2008.'],
                ['p', 'Élue en 2013 maire d’Odienné, elle est la première femme à diriger cette commune. Elle est nommée directrice générale de Côte d’Ivoire Tourisme le 5 février 2020, puis ministre de la Femme, de la Famille et de l’Enfant le 6 avril 2021.'],
            ],
            'bibliography' => [
