            ],
        ],
        [
            'slug' => 'massere-toure',
            'name' => 'Masséré Touré',
            'fullName' => 'Masséré Touré-Koné',
            'birth' => '1974',
            'birthPlace' => 'Abidjan',
            'death' => null,
            'deathPlace' => null,
            'occupations' => ['Communicante', 'Haute fonctionnaire'],
            'summary' => 'Nièce d’Alassane Ouattara, Masséré Touré est secrétaire générale de la Présidence de la République depuis décembre 2023.',
            'blocks' => [
                ['p', 'Masséré Touré-Koné, née le 30 août 1974 à Abidjan, est une communicante et haute fonctionnaire ivoirienne. Diplômée d’un diplôme d’études supérieures spécialisées en marketing et gestion commerciale des produits de l’ICN Business School de Nancy en 1998 et d’une maîtrise en langues et affaires internationales de l’université de Clermont-Ferrand, elle commence sa carrière en 1999 à la régie publicitaire du groupe Jeune Afrique, à Paris.'],
                ['h2', 'La communication de la présidence'],
                ['p', 'Rentrée en Côte d’Ivoire en 2006, elle participe à la campagne d’Alassane Ouattara. Elle est conseillère en communication du président de la République de 2010 à 2015, puis conseillère spéciale et directrice de la communication de la présidence en juillet 2018. Membre du RHDP, elle a été directrice centrale de campagne chargée de la communication du candidat en 2015.'],
                ['p', 'Nommée secrétaire générale adjointe de la présidence en janvier 2022, elle devient secrétaire générale en décembre 2023, succédant à Abdourahmane Cissé. Elle est l’épouse de Bruno Koné, ministre de la Construction, du Logement et de l’Urbanisme.'],
            ],
            'bibliography' => [
                ['title' => 'Masséré Touré', 'publisher' => 'Wikipédia en français', 'year' => null, 'url' => 'https://fr.wikipedia.org/wiki/Mass%C3%A9r%C3%A9_Tour%C3%A9'],
            ],
        ],
        [
            'slug' => 'adjaratou-traore',
            'name' => 'Adjaratou Traoré',
            'fullName' => 'Adjaratou Traoré',
            'birth' => '1971',
            'birthPlace' => 'Koumassi',
            'death' => null,
            'deathPlace' => null,
            'occupations' => ['Femme politique'],
            'summary' => 'Députée de Koumassi depuis 2021, Adjaratou Traoré est vice-présidente du Parlement de la CEDEAO.',
            'blocks' => [
                ['p', 'Adjaratou Traoré, née le 30 mars 1971 à Koumassi, est une femme politique ivoirienne membre du Rassemblement des houphouëtistes pour la démocratie et la paix (RHDP). Née et élevée dans la commune de Koumassi, elle y est élue députée lors des élections législatives du 6 mars 2021.'],
                ['h2', 'Le mandat et le leadership féminin'],
                ['p', 'Elle est vice-présidente du Parlement de la Communauté économique des États de l’Afrique de l’Ouest (CEDEAO). Candidate indépendante aux élections municipales de septembre 2023 à Koumassi, elle n’est pas élue maire.'],
                ['p', 'Elle fonde l’ONG Femmes Actrices de Développement, consacrée à l’autonomisation des femmes et à leur participation à la vie politique, et plaide pour l’application de la loi du 14 octobre 2019 qui impose un taux de 30 % de femmes parmi les candidats aux élections.'],
            ],
            'bibliography' => [
                ['title' => 'Adjaratou Traoré', 'publisher' => 'Wikipédia en français', 'year' => null, 'url' => 'https://fr.wikipedia.org/wiki/Adjaratou_Traor%C3%A9'],
            ],
        ],
        [
            'slug' => 'naya-jarvis-zamble',
            'name' => 'Naya Jarvis Zamblé',
            'fullName' => 'Naya Jarvis Zamblé',
            'birth' => '1995',
            'birthPlace' => 'Grand-Bassam',
            'death' => null,
            'deathPlace' => null,
            'occupations' => ['Cheffe d’entreprise', 'Femme politique'],
            'summary' => 'Élue députée de Gohitafla en mars 2021, Naya Jarvis Zamblé est la plus jeune députée de la législature et maire de Gohitafla depuis 2023.',
            'blocks' => [
                ['p', 'Naya Jarvis Zamblé, née le 14 octobre 1995 à Grand-Bassam, est une cheffe d’entreprise et femme politique ivoirienne. Après un diplôme universitaire de technologie en logistique et un master en management à l’université d’Accra, elle travaille au Ghana au service logistique de Nestlé-Ghana, puis rentre en Côte d’Ivoire en 2014 pour créer une ferme avicole et une entreprise d’événementiel.'],
                ['h2', 'La plus jeune députée'],
                ['p', 'Engagée au RHDP à partir de 2015, elle préside la Jeunesse féminine du parti dans la région de la Marahoué depuis 2019. En mars 2021, elle est élue députée des communes et sous-préfectures de Gohitafla, Iriéfla et Maminigui : elle est la première femme députée de cette circonscription et la plus jeune députée de la mandature.'],
                ['p', 'Après la mort du président de l’Assemblée nationale Amadou Soumahoro en mai 2022, elle se porte candidate à sa succession au nom du RHDP, avant de renoncer lorsque le président Alassane Ouattara choisit Adama Bictogo. En septembre 2023, elle est élue maire de Gohitafla.'],
            ],
            'bibliography' => [
                ['title' => 'Naya Jarvis Zamblé', 'publisher' => 'Wikipédia en français', 'year' => null, 'url' => 'https://fr.wikipedia.org/wiki/Naya_Jarvis_Zambl%C3%A9'],
            ],
        ],
    ],
