                ['title' => 'Climbié, roman', 'publisher' => 'Présence africaine', 'year' => 1956, 'url' => 'https://www.presenceafricaine.com'],
            ],
        ],
        [
            'slug' => 'jean-marie-adiaffi',
            'name' => 'Jean-Marie Adiaffi',
            'fullName' => 'Jean-Marie Adé Adiaffi',
            'birth' => '1941',
            'birthPlace' => 'Bettié',
            'death' => '1999',
            'deathPlace' => 'Abidjan',
            'occupations' => ['Écrivain', 'Philosophe', 'Réalisateur'],
            'summary' => 'Écrivain, philosophe et réalisateur ivoirien (1941-1999), Jean-Marie Adiaffi a reçu le grand prix littéraire d\'Afrique noire en 1980 pour son roman La Carte d\'identité.',
            'blocks' => [
                ['p', 'Jean-Marie Adé Adiaffi, dit Jean-Marie Adiaffi, est né le 1er janvier 1941 à Bettié, dans la région d\'Abengourou, et mort le 15 novembre 1999 à Abidjan. Écrivain, scénariste, cinéaste et critique littéraire, il est notamment l\'auteur du roman La Carte d\'identité.'],
                ['h2', 'Du cinéma à la philosophie'],
                ['p', 'Ayant perdu très tôt ses parents, il est élevé par un oncle maternel, fait son cycle primaire au village et ses études secondaires à Bingerville, puis part en France où il obtient son baccalauréat. Il s\'inscrit à l\'IDHEC, l\'Institut des hautes études cinématographiques, et effectue un stage à l\'OCORA d\'où il sort réalisateur de télévision et de cinéma. Revenu travailler à la télévision ivoirienne, il repart en France en 1966 préparer une licence et une maîtrise de philosophie à la Sorbonne, obtient son CAPES et revient en 1970 enseigner la philosophie, notamment au lycée classique d\'Abidjan.'],
                ['h2', '« La Carte d\'identité »'],
                ['p', 'Il entame sa création littéraire en 1969 avec le recueil de poèmes Yalé Sonan, puis, après plus d\'une décennie de silence, reprend sa production en 1980 en publiant La Carte d\'identité et D\'éclairs et de foudres. Son roman La Carte d\'identité, réflexion sur l\'aliénation africaine postcoloniale, reçoit le grand prix littéraire d\'Afrique noire. Suivent La Galerie infernale (1984) et Silence, on développe (1992).'],
                ['h2', 'Le « bossonisme »'],
                ['p', 'Attaché à la modernisation des religions africaines, il est le créateur du terme « bossonisme », néologisme désignant un génie auquel est rendu un culte. Jean-Marie Adiaffi meurt à Abidjan le 15 novembre 1999.'],
            ],
            'bibliography' => [
                ['title' => 'Jean-Marie Adiaffi', 'publisher' => 'Wikipédia en français', 'year' => null, 'url' => 'https://fr.wikipedia.org/wiki/Jean-Marie_Adiaffi'],
                ['title' => 'La Carte d\'identité, roman', 'publisher' => 'Hatier', 'year' => 1980, 'url' => 'https://www.hatier-clic.fr'],
            ],
        ],
        [
            'slug' => 'bernard-zadi-zaourou',
            'name' => 'Bernard Zadi Zaourou',
            'fullName' => 'Bernard Zadi Zaourou',
            'birth' => '1938',
            'birthPlace' => 'Soubré',
            'death' => '2012',
            'deathPlace' => 'Abidjan',
            'occupations' => ['Écrivain', 'Poète', 'Homme politique'],
            'summary' => "Poète et homme politique ivoirien (1938-2012), Bernard Zadi Zaourou a porté en vers la parole du peuple bété et la mémoire de l'oralité.",
            'blocks' => [
                ['p', "Bernard Zadi Zaourou, né en 1938 à Soubré, est poète et homme politique ivoirien. À la fois élu et conteur, il a fait du vers et du théâtre les véhicules d'une réflexion sur l'identité bété et la dignité du peuple."],
                ['h2', 'Le poète du peuple'],
                ['p', 'Auteur de recueils et de pièces, il puise dans les traditions orales — danses, proverbes, récits de la forêt — une langue poétique qui parle au village comme à la ville.'],
                ['h2', 'Élu et auteur'],
                ['p', "Ministre et député, il poursuit son écriture tout au long de sa carrière politique. Il meurt à Abidjan en 2012, laissant une oeuvre où la poésie et l'engagement public se répondent."],
            ],
            'bibliography' => [
                ['title' => 'Bernard Zadi Zaourou', 'publisher' => 'Wikipédia en français', 'year' => null, 'url' => 'https://fr.wikipedia.org/wiki/Bernard_Zadi_Zaourou'],
            ],
        ],
        [
            'slug' => 'ake-loba',
            'name' => 'Aké Loba',
            'fullName' => 'Aké Loba',
            'birth' => '1927',
            'birthPlace' => 'Abidjan',
            'death' => '2012',
            'deathPlace' => 'Aix-en-Provence (France)',
            'occupations' => ['Écrivain', 'Diplomate', 'Homme politique'],
            'summary' => 'Écrivain, diplomate et homme politique ivoirien (1927-2012), Aké Loba a été en 1961 le premier lauréat du grand prix littéraire d\'Afrique noire pour Kocoumbo, l\'étudiant noir.',
            'blocks' => [
                ['p', 'Aké Loba, né le 15 août 1927 à Abidjan et mort le 2 août 2012 à Aix-en-Provence, est un écrivain, homme politique et diplomate ivoirien. Fils d\'un chef traditionnel ébrié, il est scolarisé en 1939 à l\'école primaire publique de Grand-Bassam.'],
                ['h2', 'De la ferme bretonne à « Kocoumbo »'],
                ['p', 'En 1947, il part en France pour apprendre l\'agriculture : employé un an dans une ferme bretonne près de Quimper, il passe six mois en Beauce avant de s\'installer à Paris en 1948. Planton, caissier puis comptable à partir de 1956, il obtient le baccalauréat en 1958 et rentre en Côte d\'Ivoire, où il commence à écrire ce qui deviendra Kocoumbo, l\'étudiant noir, achevé en 1959 et publié en 1960 par Flammarion.'],
                ['h2', 'Le premier lauréat du grand prix littéraire d\'Afrique noire'],
                ['p', 'En 1961, Aké Loba devient le premier lauréat du grand prix littéraire d\'Afrique noire grâce à Kocoumbo, l\'étudiant noir. Il remporte aussi le prix littéraire Houphouët-Boigny en 1969 avec son deuxième roman, Sagaies sous le fleuve, achevé dès 1966 et publié quatre ans plus tard sous le titre Les Fils de Kouretcha. Il publie en 1973 Les Dépossédés.'],
                ['h2', 'Le diplomate et l\'élu'],
                ['p', 'Après l\'indépendance, il est secrétaire d\'ambassade à Bonn de 1961 à 1965, puis conseiller d\'ambassade à Rome de 1965 à 1970. Député, il est maire de la commune d\'Abobo, à Abidjan, de 1985 à 1990. Il meurt dans sa maison d\'Aix-en-Provence en août 2012.'],
            ],
            'bibliography' => [
                ['title' => 'Aké Loba', 'publisher' => 'Wikipédia en français', 'year' => null, 'url' => 'https://fr.wikipedia.org/wiki/Ak%C3%A9_Loba'],
                ['title' => 'Kocoumbo, l\'étudiant noir, roman', 'publisher' => 'Flammarion', 'year' => 1960, 'url' => 'https://www.flammarion.com'],
            ],
