            'death' => '2023',
            'deathPlace' => 'Abidjan',
            'occupations' => ['Écrivain', 'Homme politique'],
            'summary' => 'Écrivain et homme politique ivoirien (1938-2023), Paul Yao Akoto a été ministre de l\'Éducation nationale de 1971 à 1983 et a publié le roman L\'Envol des tisserins en 1986.',
            'blocks' => [
                ['p', 'Paul Yao Akoto, connu sous le nom de Paul Akoto Yao, est né le 12 avril 1938 à Sakassou et mort le 16 janvier 2023 à Abidjan. Ancien élève de l\'École normale supérieure de Saint-Cloud, premier agrégé de biologie ivoirien, il est écrivain et homme politique.'],
                ['h2', 'Ministre de l\'Éducation nationale'],
                ['p', 'Il enseigne à l\'École normale supérieure d\'Abidjan, puis devient directeur général adjoint et directeur général de l\'Enseignement. Le 1er décembre 1971, il est nommé ministre de l\'Éducation nationale, fonction qu\'il occupe pendant douze ans jusqu\'à son limogeage, le 18 novembre 1983.'],
                ['h2', 'L\'écrivain'],
                ['p', 'Son œuvre littéraire la plus connue est L\'Envol des tisserins, paru en 1986 ; il a aussi publié L\'Escalier aux sept marches (1992), Le Cri du jour (1995) et des Chroniques ivoiriennes. Il a été vice-président de l\'Assemblée nationale, membre du conseil exécutif de l\'UNESCO et président de l\'UDPCI.'],
            ],
            'bibliography' => [
                ['title' => 'Paul Yao Akoto', 'publisher' => 'Wikipédia en français', 'year' => null, 'url' => 'https://fr.wikipedia.org/wiki/Paul_Yao_Akoto'],
            ],
        ],
        [
