            'name' => 'Marcel Amondji',
            'fullName' => 'Marcel Anoma',
            'birth' => '1934',
            'birthPlace' => 'Anono',
            'death' => '2021',
            'deathPlace' => 'Perpignan (France)',
            'occupations' => ['Écrivain', 'Historien'],
            'summary' => 'Écrivain et historien ivoirien (1934-2021), Marcel Amondji, de son vrai nom Marcel Anoma, a publié une histoire critique de la Côte d\'Ivoire post-indépendance.',
            'blocks' => [
                ['p', 'Marcel Amondji, de son vrai nom Marcel Anoma, est un écrivain et historien ivoirien, né en 1934 à Anono et mort à Perpignan en 2021. Il a passé toute son enfance à Bingerville.'],
                ['h2', 'Les « chevaliers de l\'Aventure »'],
                ['p', 'Il est l\'un des premiers boursiers ivoiriens envoyés en France en 1946 — les fameux « chevaliers de l\'Aventure » —, où il fait toutes ses études secondaires et supérieures. Depuis 1961, il vit en France.'],
                ['h2', 'L\'opposant en exil'],
                ['p', 'Marcel Amondji a été l\'un des farouches opposants à la politique d\'Houphouët-Boigny dès les premières heures de l\'indépendance de la Côte d\'Ivoire. Son opposition lui a valu une très longue vie d\'exil en Algérie, puis en France.'],
                ['h2', 'L\'historien de la Côte d\'Ivoire'],
                ['p', 'Bien informé sur l\'histoire et l\'actualité de son pays, il est un écrivain qui a la stature d\'un historien. Il a publié Félix Houphouët et la Côte-d\'Ivoire. L\'envers d\'une légende (Karthala, 1984), Côte d\'Ivoire : Le PDCI et la vie politique de 1944 à 1985 (L\'Harmattan, 1986), Côte d\'Ivoire : La dépendance et l\'épreuve des faits (L\'Harmattan, 1988), L\'Afrique noire au miroir de l\'Occident (Éditions nouvelles du Sud, 1993) et Sidjè ou La Marche des femmes sur la prison de Grand-Bassam (2007).'],
            ],
            'bibliography' => [
                ['title' => 'Marcel Amondji', 'publisher' => 'Wikipédia en français', 'year' => null, 'url' => 'https://fr.wikipedia.org/wiki/Marcel_Amondji'],
                ['title' => 'Félix Houphouët et la Côte-d\'Ivoire. L\'envers d\'une légende', 'publisher' => 'Karthala', 'year' => 1984, 'url' => 'https://www.karthala.com'],
            ],
        ],
        [
            'slug' => 'sery-bailly',
            'name' => 'Séry Bailly',
            'fullName' => 'Zacharie Séry Bailly',
            'birth' => '1948',
            'birthPlace' => 'Abidjan',
            'death' => '2018',
            'deathPlace' => 'Abidjan',
            'occupations' => ['Universitaire', 'Écrivain', 'Homme politique'],
            'summary' => 'Universitaire, écrivain et homme politique ivoirien (1948-2018), Séry Bailly a enseigné la littérature anglophone à Abidjan et été ministre de l\'Enseignement supérieur puis de la Communication.',
            'blocks' => [
                ['p', 'Zacharie Séry Bailly, dit Séry Bailly, est né le 13 mars 1948 à Abidjan et mort le 2 décembre 2018 dans la même ville. Universitaire, académicien, écrivain et homme politique, il est vice-président de l\'Académie des sciences, des arts, des cultures d\'Afrique et des diasporas africaines.'],
                ['h2', 'L\'université et la gauche ivoirienne'],
                ['p', 'Professeur d\'anglais à l\'université d\'Abidjan-Cocody, il devient doyen de l\'UFR des langues et civilisations. Membre du Front populaire ivoirien depuis 1993, il est arrêté en 1971 sur le campus et déporté à Séguéla, où il a Laurent Gbagbo pour compagnon de détention.'],
                ['h2', 'Ministre et chroniqueur'],
                ['p', 'Il entre au gouvernement le 4 janvier 2000 comme ministre de l\'Enseignement supérieur et de la Recherche scientifique, est élu député de Daloa en décembre 2000, puis devient ministre de la Communication le 5 août 2002, jusqu\'au 13 mars 2003. Ses « Chroniques de notre temps », publiées dans Notre Temps de 1991 à 1994, l\'ont fait connaître du grand public.'],
            ],
            'bibliography' => [
                ['title' => 'Séry Bailly', 'publisher' => 'Wikipédia en français', 'year' => null, 'url' => 'https://fr.wikipedia.org/wiki/S%C3%A9ry_Bailly'],
            ],
        ],
        [
            'slug' => 'frederic-bruly-bouabre',
            'name' => 'Frédéric Bruly Bouabré',
            'fullName' => 'Frédéric Bruly Bouabré',
            'birth' => '1923',
            'birthPlace' => 'Zéprégühé (Daloa)',
            'death' => '2014',
            'deathPlace' => 'Abidjan',
            'occupations' => ['Dessinateur', 'Poète'],
            'summary' => 'Dessinateur et poète ivoirien (1923-2014), Frédéric Bruly Bouabré a inventé un syllabaire bété de 448 signes pour sauver de l\'oubli la culture de son peuple.',
            'blocks' => [
                ['p', 'Frédéric Bruly Bouabré est né le 11 mars 1923 à Zéprégühé, dans la région de Daloa, et mort le 28 janvier 2014 à Abidjan. Dessinateur et poète, il est l\'inventeur de l\'écriture bété, une écriture spécifiquement africaine destinée à sauver de l\'oubli la culture du peuple bété.'],
                ['h2', 'La révélation de 1948'],
                ['p', 'Engagé dans la Marine pendant la Seconde Guerre mondiale, il pratique plusieurs métiers avant de devenir fonctionnaire. À la suite d\'une « révélation divine » qu\'il reçoit en songe le 11 mars 1948, il se consacre à donner à l\'Afrique une écriture entièrement africaine et se fait appeler « Cheik Nadro », « le Révélateur ».'],
                ['h2', 'Un syllabaire de 448 signes'],
                ['p', 'Il crée un syllabaire composé de 448 signes désignant chacun une syllabe : l\'alphabet bété, dont il reproduit l\'ensemble des syllabes sur de petites cartes en carton. Pour cela, il s\'inspire de figures géométriques découvertes sur des pierres d\'un village du pays bété, et retranscrit avec cette écriture des contes, des textes de la tradition bété et des poèmes. Ses recherches sont publiées en 1958 par Théodore Monod.'],
                ['h2', 'Une œuvre exposée dans le monde'],
                ['p', 'Son œuvre est exposée pour la première fois en Europe en 1989, lors de l\'exposition Magiciens de la terre. Elle est ensuite présentée à Londres, Berlin, Francfort, à l\'Institut du monde arabe et à la Tate Modern en 2010, ainsi que dans les Biennales de Venise, de Sydney, de São Paulo, de Dakar et d\'Istanbul, à Documenta XI en 2002 et à Africa Remix en 2005. En 2006, le musée d\'art moderne et contemporain de Genève lui consacre une exposition intitulée Connaissances du Monde.'],
            ],
            'bibliography' => [
                ['title' => 'Frédéric Bruly Bouabré', 'publisher' => 'Wikipédia en français', 'year' => null, 'url' => 'https://fr.wikipedia.org/wiki/Fr%C3%A9d%C3%A9ric_Bruly_Bouabr%C3%A9'],
            ],
        ],
        [
            'slug' => 'isaie-biton-koulibaly',
            'name' => 'Isaïe Biton Koulibaly',
            'fullName' => 'Isaïe Biton Koulibaly',
            'birth' => '1949',
            'birthPlace' => 'Abidjan (Treichville)',
            'death' => '2021',
            'deathPlace' => 'Abidjan',
            'occupations' => ['Romancier', 'Nouvelliste'],
            'summary' => 'Romancier et nouvelliste ivoirien (1949-2021), Isaïe Biton Koulibaly a dirigé pendant plus de trente ans le service littéraire des Nouvelles Éditions ivoiriennes.',
            'blocks' => [
                ['p', 'Isaïe Biton Koulibaly est né le 7 juin 1949 à Abidjan-Treichville et mort dans la même ville le 10 novembre 2021. Romancier et nouvelliste, il est spécialisé dans la littérature de genre — fantastique, romance — et compte parmi les auteurs les plus lus de Côte d\'Ivoire.'],
                ['h2', 'Un passeur de la littérature ivoirienne'],
                ['p', 'Correspondant permanent du magazine Amina pendant plus de quinze ans, il dirige le service littéraire des Nouvelles Éditions ivoiriennes pendant plus de trente ans, avant de faire valoir ses droits à la retraite le 13 janvier 2005.'],
                ['h2', 'Prix et reconnaissance'],
                ['p', 'Il obtient le prix Nyonda en 2002 pour Merci l\'artiste, le grand prix ivoirien des lettres en 2005 avec La Puissance de la lecture et le prix Yambo Ouologuem en 2008 pour Et pourtant, elle pleurait.'],
            ],
            'bibliography' => [
                ['title' => 'Isaïe Biton Koulibaly', 'publisher' => 'Wikipédia en français', 'year' => null, 'url' => 'https://fr.wikipedia.org/wiki/Isa%C3%AFe_Biton_Koulibaly'],
            ],
        ],
        [
            'slug' => 'pierre-kipre',
            'name' => 'Pierre Kipré',
            'fullName' => 'Pierre Kipré',
            'birth' => '1945',
            'birthPlace' => 'Daloa',
            'death' => null,
            'deathPlace' => null,
            'occupations' => ['Historien', 'Écrivain', 'Homme politique'],
            'summary' => 'Historien et homme politique ivoirien né en 1945 à Daloa, Pierre Kipré a été ministre de l\'Éducation nationale de 1993 à 1999, puis ambassadeur de Côte d\'Ivoire en France.',
            'blocks' => [
                ['p', 'Pierre Kipré est né le 23 février 1945. Historien et écrivain originaire de Daloa, dans l\'Ouest de la Côte d\'Ivoire, il a été ministre de l\'Éducation nationale, puis ambassadeur de Côte d\'Ivoire en France.'],
                ['h2', 'L\'universitaire'],
                ['p', 'Après des études en France, où il obtient successivement son baccalauréat de série A et philosophie en 1965, son certificat d\'aptitude au professorat du second degré en 1972 et son doctorat en lettres et sciences humaines en 1981, il revient en Côte d\'Ivoire. Il y occupe divers postes à l\'École normale supérieure d\'Abidjan, son ancien établissement, avant de devenir en 1986 professeur titulaire d\'histoire contemporaine.'],
                ['h2', 'Ministre puis ambassadeur'],
                ['p', 'Il est nommé ministre de l\'Éducation nationale de Côte d\'Ivoire le 15 décembre 1993, en remplacement de Touré Saliou, et le reste jusqu\'au 10 août 1999. Il assure ensuite les fonctions d\'ambassadeur de la Côte d\'Ivoire en France, avec résidence à Paris, jusqu\'en 2010 et son remplacement par Ally Coulibaly.'],
                ['h2', 'L\'historien de la Côte d\'Ivoire'],
                ['p', 'Ses travaux portent sur les villes coloniales, le syndicalisme et la formation de la nation ivoirienne. Il a notamment publié Daloa, une cité dans l\'histoire (1985), Villes de Côte d\'Ivoire, 1893-1940 (1985-1986), Le congrès de Bamako ou La naissance du RDA (1989), Histoire de Côte d\'Ivoire (1991), Démocratie et société en Côte d\'Ivoire (2000) et Côte d\'Ivoire : la formation d\'un peuple (2005).'],
            ],
            'bibliography' => [
                ['title' => 'Pierre Kipré', 'publisher' => 'Wikipédia en français', 'year' => null, 'url' => 'https://fr.wikipedia.org/wiki/Pierre_Kipr%C3%A9'],
            ],
        ],
        [
            'slug' => 'veronique-tadjo',
            'name' => 'Véronique Tadjo',
            'fullName' => 'Véronique Tadjo',
            'birth' => '1955',
            'birthPlace' => 'Paris (France)',
            'death' => null,
            'deathPlace' => null,
            'occupations' => ['Écrivaine', 'Poétesse', 'Illustratrice'],
            'summary' => 'Écrivaine franco-ivoirienne née en 1955, Véronique Tadjo écrit poésie, romans et livres pour la jeunesse, et a reçu le Grand prix littéraire d’Afrique noire en 2005.',
            'blocks' => [
                ['p', 'Véronique Tadjo, née le 21 juillet 1955 à Paris, est une écrivaine franco-ivoirienne, auteure de poèmes, de romans et d’ouvrages pour la jeunesse, qu’elle illustre elle-même. Elle se consacre également à la peinture.'],
                ['h2', 'L’écriture et l’illustration'],
                ['p', 'Son œuvre aborde des sujets historiques et intimes, notamment le génocide rwandais dans L’Ombre d’Imana. Elle écrit aussi pour les enfants et illustre ses propres albums, ce qui lui donne une place singulière dans la littérature ivoirienne.'],
                ['h2', 'Une carrière internationale'],
                ['p', 'Après de longs séjours au Kenya et en Angleterre, elle s’installe en Afrique du Sud, où elle dirige le département de français de l’université du Witwatersrand à Johannesburg. Elle vit depuis en Europe ou en Afrique de l’Ouest et a reçu le Grand prix littéraire d’Afrique noire en 2005.'],
            ],
            'bibliography' => [
                ['title' => 'Véronique Tadjo', 'publisher' => 'Wikipédia en français', 'year' => null, 'url' => 'https://fr.wikipedia.org/wiki/V%C3%A9ronique_Tadjo'],
            ],
