            'blocks' => [
                ['p', 'Charles Zégoua Gbessi Nokan, né à Yamoussoukro le 28 décembre 1936 et mort à Abidjan le 1er novembre 2022, est un universitaire et écrivain ivoirien membre de l’Académie des sciences, des arts, des cultures d’Afrique et des diasporas africaines (ASCAD).'],
                ['h2', 'Le soleil noir point'],
                ['p', 'Après des études secondaires et supérieures en France, il publie Le soleil noir point en 1962 et Violent était le vent en 1966. Sa première pièce, Les malheurs de Tchakô, paraît en 1968, suivie d’Abraha Pokou ou Une grande africaine en 1970 et du recueil La voix grave d’Ophimoï.'],
                ['h2', 'Une écriture engagée'],
                ['p', 'Pour Charles Nokan, l’écriture est à la fois combat, chant et danse. Son autobiographie Tel que je suis reçoit le Grand prix national de littérature en 2014, et il obtient le Prix d’exception au Grand Prix Kaïlcedra des lycées et collèges en 2015.'],
            ],
            'bibliography' => [
                ['title' => 'Charles Nokan', 'publisher' => 'Wikipédia en français', 'year' => null, 'url' => 'https://fr.wikipedia.org/wiki/Charles_Nokan'],
