            'summary' => 'Dramaturge et romancier ivoirien né en 1956, Koffi Kwahulé est l’un des auteurs africains les plus joués, lauréat du prix Ahmadou-Kourouma pour Babyface.',
            'blocks' => [
                ['p', 'Koffi Kwahulé, né le 17 mai 1956 à Abengourou, est un comédien, metteur en scène, dramaturge et romancier ivoirien.'],
                ['h2', 'Le jazz et la scène'],
                ['p', 'Son écriture est très influencée par le jazz, qui lui donne sa musicalité et une implication politique et historique comparable. Pour L’Odeur des arbres, il reçoit en 2017 le grand prix de littérature dramatique, puis le prix Bernard-Marie-Koltès en 2018.'],
                ['h2', 'Les prix'],
                ['p', 'Son roman Babyface obtient le prix Ahmadou-Kourouma en 2006. Il reçoit également le prix Émile Augier de l’Académie française en 2026, le prix Mokanda et le prix national d’excellence pour la littérature de Côte d’Ivoire en 2015, ainsi que le prix Édouard-Glissant en 2013.'],
