            'blocks' => [
                ['p', 'Venance Kouassi Konan, né le 12 décembre 1958 à Bocanda, est un journaliste, écrivain et homme de médias ivoirien. Il est récompensé à plusieurs reprises par le prix Ebony comme journaliste.'],
                ['h2', 'Les Prisonniers de la haine'],
                ['p', 'Il publie en 2003 le roman Les Prisonniers de la haine, puis Robert et les catapila en 2005, Nègreries en 2007, Les catapila, ces ingrats en 2009 et Chroniques afro-sarcastiques en 2011. Sa biographie d’Edem Kodjo, un homme, un destin, lui vaut le Grand prix littéraire d’Afrique noire en 2012.'],
                ['h2', 'La presse'],
                ['p', 'Il dirige Fraternité Matin de 2011 à 2021, avant d’être nommé au conseil d’administration de la Société ivoirienne de télédiffusion, qu’il préside ensuite. Il reçoit le prix de la presse panafricaine en 2018.'],
            ],
