            'death' => '2017',
            'deathPlace' => 'Abidjan',
            'occupations' => ['Romancière'],
            'summary' => 'Romancière ivoirienne (1955-2017), Regina Yaou a raconté le quotidien et le statut des femmes, du roman littéraire aux collections sentimentales.',
            'blocks' => [
                ['p', 'Régina Yaou, née le 10 juillet 1955 à Dabou et morte le 4 novembre 2017 à Abidjan, est une romancière ivoirienne. Élevée par sa tante sage-femme dans une famille passionnée de lecture, elle écrit ses premiers poèmes entre 12 et 14 ans.'],
                ['h2', 'Lezou Marie et La Révolte d’Affiba'],
                ['p', 'Après un prix littéraire en 1977 et des études à Tours puis à Abidjan, elle publie son premier roman, Lezou Marie ou les écueils de la vie, en 1982, suivi de La Révolte d’Affiba en 1985. Ses œuvres abordent la violence domestique, l’infidélité, la maternité et la stérilité.'],
                ['h2', 'Une romancière reconnue'],
                ['p', 'À partir de la fin des années 1990, elle publie aussi sous pseudonymes dans la collection Adoras. Elle séjourne aux États-Unis comme consultante et conférencière, reçoit le Prix national d’excellence pour la littérature en 2014 et est l’auteure à l’honneur du Salon international du livre d’Abidjan en 2016.'],
            ],
            'bibliography' => [
                ['title' => 'Regina Yaou', 'publisher' => 'Wikipédia en français', 'year' => null, 'url' => 'https://fr.wikipedia.org/wiki/Regina_Yaou'],
            ],
