            'blocks' => [
                ['p', 'François-Joseph Amon d’Aby, également connu sous le nom d’Amon Koutouan, né le 17 juillet 1913 à Aby, dans le Sud-Comoé, et mort le 10 janvier 2007, est un écrivain ivoirien d’expression française.'],
                ['h2', 'Le théâtre et les archives'],
