            'occupations' => ['Écrivain', 'Universitaire'],
            'summary' => 'Écrivain et universitaire ivoirien né en 1953, Amadou Koné est l’auteur des Frasques d’Ebinto et enseigne aux États-Unis.',
            'blocks' => [
                ['p', 'Amadou Koné, né en mai 1953 à Tangora, dans le cercle de Banfora, est un écrivain et universitaire ivoirien. Il grandit dans une plantation près d’Ayamé et commence ses études primaires en Côte d’Ivoire en 1958.'],
                ['h2', 'Les Frasques d’Ebinto'],
                ['p', 'Il est surtout connu pour Les Frasques d’Ebinto, roman qui suit un jeune lycéen brillant obligé d’abandonner ses études pour assumer une paternité. Il traite aussi de la sorcellerie dans Jusqu’au seuil de l’irréel et écrit Samory de Bissandougou et Kaméléfata ou les ennemis de la traite.'],
                ['h2', 'L’universitaire'],
                ['p', 'Après des études à la faculté des lettres de l’université d’Abidjan, il obtient le quatrième prix du Concours théâtral inter-africain en 1972. Depuis 1997, il enseigne la littérature, la culture et l’histoire africaines à l’université de Georgetown, à Washington.'],
            ],
            'bibliography' => [
                ['title' => 'Amadou Koné', 'publisher' => 'Wikipédia en français', 'year' => null, 'url' => 'https://fr.wikipedia.org/wiki/Amadou_Kon%C3%A9'],
