            'birth' => '1955',
            'birthPlace' => 'Soubré',
            'death' => null,
            'deathPlace' => null,
            'occupations' => ['Écrivaine', 'Universitaire'],
            'summary' => 'Écrivaine ivoirienne née en 1955, Fatou Keïta a abordé l’excision dans Rebelle et écrit de nombreux livres pour la jeunesse.',
            'blocks' => [
                ['p', 'Fatou Keïta, née en 1955 à Soubré, est une écrivaine ivoirienne. Docteure et enseignante-chercheuse à la faculté d’anglais de l’université Houphouët-Boigny d’Abidjan, elle est ancienne doyenne de cette faculté et spécialiste de civilisation britannique.'],
                ['h2', 'Rebelle'],
                ['p', 'Son premier roman destiné aux adultes, Rebelle, aborde un sujet longtemps tabou en Côte d’Ivoire : l’excision. Elle publie ensuite Et l’aube se leva, récit des difficultés d’une jeune femme aisée qui se libère de l’influence de son milieu.'],
                ['h2', 'La littérature de jeunesse'],
                ['p', 'Elle écrit surtout des nouvelles pour enfants, où elle traite de problèmes de société, comme le sida dans Un arbre pour Lollie. Elle reçoit le premier prix du concours de littérature africaine pour enfant de l’ACCT en 1994, une mention de l’UNESCO en 1997, le Prix Jeanne de Cavally en 2018 et le Prix national d’excellence de littérature et des arts en 2023.'],
            ],
            'bibliography' => [
                ['title' => 'Fatou Keïta', 'publisher' => 'Wikipédia en français', 'year' => null, 'url' => 'https://fr.wikipedia.org/wiki/Fatou_Ke%C3%AFta'],
            ],
        ],
        [
            'slug' => 'gauz',
            'name' => 'Gauz',
            'fullName' => 'Armand Patrick Gbaka-Brédé',
            'birth' => '1971',
            'birthPlace' => 'Abidjan',
            'death' => null,
            'deathPlace' => null,
            'occupations' => ['Romancier', 'Scénariste', 'Photographe'],
            'summary' => 'Romancier ivoirien né en 1971, Gauz a écrit Debout-Payé et Camarade Papa, et reçu le Grand prix littéraire d’Afrique noire en 2019.',
            'blocks' => [
                ['p', 'Gauz est le nom de plume d’Armand Patrick Gbaka-Brédé, né le 22 mars 1971 à Abidjan. Il grandit entre Attécoubé, Agnibilékrou, Yopougon, Bouaké, Daloa et Cocody, et parle agni à la maison.'],
                ['h2', 'Debout-Payé'],
                ['p', 'Arrivé en France en 1999 pour un master de biochimie, il travaille deux ans comme vigile. Son premier roman, Debout-Payé, paraît en 2014 et reçoit le premier prix des libraires Gibert Joseph. Camarade Papa, paru en 2018, traite de la colonisation et obtient le Grand prix littéraire d’Afrique noire en 2019.'],
                ['h2', 'L’éditeur'],
                ['p', 'Photographe, scénariste et rédacteur en chef d’un journal économique satirique ivoirien, il publie Black Manoo en 2020 et Les Portes en 2024. En 2022, il crée sa propre maison d’édition en Côte d’Ivoire, les éditions Srèlè, et fait paraître Cocoaïans, une histoire politique du chocolat.'],
            ],
            'bibliography' => [
                ['title' => 'Gauz', 'publisher' => 'Wikipédia en français', 'year' => null, 'url' => 'https://fr.wikipedia.org/wiki/Gauz'],
            ],
        ],
        [
            'slug' => 'werewere-liking',
            'name' => 'Werewere-Liking',
            'fullName' => 'Eddy-Njock N. Wetewete-Liking',
            'birth' => '1950',
            'birthPlace' => 'Bondé (Cameroun)',
            'death' => null,
            'deathPlace' => null,
            'occupations' => ['Romancière', 'Dramaturge', 'Artiste'],
            'summary' => 'Artiste et écrivaine panafricaine née en 1950 au Cameroun et installée en Côte d’Ivoire, Werewere-Liking a fondé le village Ki-Yi et publié plus de trente œuvres.',
            'blocks' => [
                ['p', 'Eddy-Njock N. Wetewete-Liking, épouse Gnepo, dite Werewere-Liking, est une artiste pluridisciplinaire panafricaine née en 1950 à Bondé, au Cameroun, et installée en Côte d’Ivoire depuis 1978. Chanteuse, danseuse, actrice, peintre, romancière, essayiste, poète et metteuse en scène, elle commence par la poésie et le chant en 1966.'],
                ['h2', 'Le Ki-Yi M’Bock'],
                ['p', 'En 1985, elle crée à Abidjan son propre groupe, le Ki-Yi M’Bock, avec lequel elle met en scène plus d’une trentaine de spectacles. L’expérience devient un centre de formation agréé en 1997, puis la Fondation Panafricaine Ki-Yi M’Bock en 2001, qui a formé des artistes comme Dobet Gnahoré, King Mensah ou Manou Gallo.'],
                ['h2', 'L’œuvre'],
                ['p', 'Elle compte plus de trente œuvres publiées : poésie, théâtre, romans, essais, livres d’art, récits et contes, dont Orphée d’Afrique et La Mémoire amputée. Ce dernier roman lui vaut le prix Noma en 2005 et le Barnes & Noble Book of the Year à New York. Elle cède la direction artistique du village Ki-Yi en septembre 2021.'],
            ],
            'bibliography' => [
                ['title' => 'Werewere-Liking', 'publisher' => 'Wikipédia en français', 'year' => null, 'url' => 'https://fr.wikipedia.org/wiki/Werewere-Liking'],
            ],
        ],
