                ['h2', 'Archives et douanes'],
                ['p', 'Il travaille au service des archives nationales de 1965 à 1967, sous la direction de François-Joseph Amon d’Aby, puis intègre l’école des douanes de Neuilly-sur-Seine de 1968 à 1970 et l’école de navigation de La Rochelle, où il se spécialise comme douanier marin des unités de garde-côtes. Il rentre en Côte d’Ivoire en juillet 1971.'],
                ['h2', 'Le poète'],
                ['p', 'Il est l’auteur de plusieurs recueils composés entre 1952 et 1971, dont Cloches et grelots (1953), La Maison isolée (1963) et L’Harmonica oublié (1966). Poète et nouvelliste, il figure parmi les pionniers de la poésie ivoirienne aux côtés d’Aké Loba, Bernard Dadié, Anoma Kanié et Michel Thew Adjié.'],
