            'blocks' => [
                ['p', 'Michel Thew Adjié, de son vrai nom Michel Bonny Aka, né le 23 novembre 1924 à Jacqueville, est un dramaturge, poète, conteur, romancier, nouvelliste et enseignant ivoirien.'],
                ['h2', 'Chants et pleurs avant l’aurore'],
                ['p', 'Il incarne, avec Bernard Dadié, Aké Loba, Anoma Kanié et Bertin Doutéo, la première génération d’écrivains ivoiriens publiés en français, dès la parution de son recueil Chants et pleurs avant l’aurore en 1951. Sa pièce Kadjoum est jouée pour la première fois en 1954.'],
                ['h2', 'L’engagement et l’oubli'],
                ['p', 'Opposé à la ségrégation raciale et à la colonisation, il revendique l’influence du marxisme, de Gandhi et de Jésus. Incarcéré dans l’affaire des complots de 1963 et condamné à cinq ans de travaux forcés, il est libéré en 1966 et continue d’écrire pour le théâtre, avant de tomber progressivement dans l’oubli.'],
