                ['p', 'Alphonse Tiérou, né le 17 avril 1946 à Dabou et mort le 11 août 2021 à Paris, est un chercheur, chorégraphe, écrivain et pédagogue ivoirien. Il étudie à l’Institut national des arts d’Abidjan.'],
                ['h2', 'La notation de la danse'],
                ['p', 'Il crée en 1983 une notation du vocabulaire et de la gestuelle de la danse africaine. Consultant à l’UNESCO pour la recherche sur la danse en Afrique de 1988 à 1996, il forme des danseurs et chorégraphes dans une vingtaine de pays africains.'],
                ['h2', 'L’écrivain et le pédagogue'],
                ['p', 'Il est l’initiateur des Premières Rencontres de la création chorégraphique panafricaine de Luanda en 1995 et fonde à Paris le Centre de ressources, de pédagogie et de recherche pour la création africaine. Ses livres et articles sont parmi les premiers à théoriser la danse africaine.'],
