            'birth' => '1955',
            'birthPlace' => 'Bouaké',
            'death' => null,
            'deathPlace' => null,
            'occupations' => ['Écrivain', 'Dramaturge', 'Journaliste'],
            'summary' => 'Écrivain, dramaturge et journaliste ivoirien né en 1955, Tiburce Koffi est une voix engagée de la scène culturelle et a dirigé le Palais de la Culture de Treichville.',
            'blocks' => [
                ['p', 'Tiburce Jules Koffi, né le 12 avril 1955 à Bouaké, est un écrivain, dramaturge, journaliste, chroniqueur et homme politique ivoirien. Après des études supérieures en lettres modernes, il enseigne avant de rejoindre le journalisme et de collaborer avec plusieurs journaux ivoiriens de premier plan.'],
                ['h2', 'Le théâtre et la critique'],
                ['p', 'Il se fait connaître par ses prises de position tranchées, ses chroniques engagées et ses pièces à portée sociale et politique, jouées sur de nombreuses scènes ivoiriennes et africaines. Sa plume, à la fois critique et poétique, aborde les réalités contemporaines de l’Afrique, la gouvernance, les inégalités et la condition humaine.'],
                ['h2', 'L’institution culturelle'],
                ['p', 'Il occupe des fonctions de direction dans des institutions culturelles majeures, notamment comme directeur général du Palais de la Culture de Treichville, et devient conseiller spécial chargé de la culture auprès du président de la République. En août 2026, il reçoit le prix d’excellence dans la catégorie littérature.'],
            ],
            'bibliography' => [
                ['title' => 'Tiburce Koffi', 'publisher' => 'Wikipédia en français', 'year' => null, 'url' => 'https://fr.wikipedia.org/wiki/Tiburce_Koffi'],
            ],
