            'occupations' => ['Écrivain', 'Enseignant'],
            'summary' => 'Enseignant et écrivain ivoirien né en 1962, Zan Tiato Daniel est maître-assistant à l’INSAAC et l’auteur d’une œuvre nourrie par les traditions dan.',
            'blocks' => [
                ['p', 'Zan Tiato Daniel, né le 2 mars 1962 à Souapleu, dans la sous-préfecture de Bin-Houyé, est un enseignant et écrivain ivoirien. Après son éducation primaire dans son village, il étudie au collège Enfant Jésus et Saint-Jean de Gagnoa, au lycée Saint-Viateur de Bouaké, puis à l’École normale supérieure d’Abidjan.'],
                ['h2', 'L’enseignant-chercheur'],
                ['p', 'Enseignant certifié de lettres modernes dans plusieurs lycées, il occupe divers postes à la Commission nationale ivoirienne pour l’UNESCO entre 2008 et 2019. Il soutient en 2016 une thèse de doctorat à l’université Alassane Ouattara de Bouaké et devient en 2019 enseignant-chercheur à l’Institut national supérieur des arts et de l’action culturelle (INSAAC), où il est maître-assistant du CAMES.'],
                ['h2', 'L’écrivain des traditions dan'],
                ['p', 'Entre 2013 et 2023, il publie Le testament du millénium (roman, 2013), Le serment (contes et légendes dan, 2014), Les cinq doigts de la main (récits pour enfants, 2015), Le secret de famille (nouvelles, 2022) et Le mystère de la naissance (contes et proverbes dan, 2022), ainsi que deux ouvrages coécrits avec Mira Sun. Il est secrétaire général du comité scientifique du Festival des arts et de la culture Dan Tonkpi Nihidaley.'],
            ],
            'bibliography' => [
                ['title' => 'Zan Tiato Daniel', 'publisher' => 'Wikipédia en français', 'year' => null, 'url' => 'https://fr.wikipedia.org/wiki/Zan_Tiato_Daniel'],
