            'summary' => 'Écrivaine et traductrice ivoirienne née en 1980, Edwige-Renée Dro a été distinguée par Africa39 et a cofondé le collectif Abidjan Lit.',
            'blocks' => [
                ['p', 'Edwige-Renée Dro, née en 1980 à Odienné, dans le nord-ouest de la Côte d’Ivoire, est une écrivaine, traductrice et militante littéraire ivoirienne. Son père est professeur de mathématiques et sa mère commerçante.'],
                ['h2', 'Africa39 et Abidjan Lit'],
                ['p', 'En 2014, elle figure parmi les lauréates du projet Africa39, qui met en lumière trente-neuf jeunes écrivains africains de moins de quarante ans, et paraît dans l’anthologie Africa39: New Writing from Africa South of the Sahara. En 2016, elle est juge du prix PEN International New Voices et cofonde le collectif littéraire Abidjan Lit.'],
                ['h2', 'La bibliothèque 1949'],
                ['p', 'En 2018, elle obtient une bourse d’écriture Morland. Elle inaugure à Yopougon une bibliothèque publique axée sur l’écriture des femmes d’Afrique et de la diaspora noire, nommée « 1949 » pour commémorer les femmes ivoiriennes qui, en 1949, marchèrent contre le pouvoir colonial. Elle participe en 2019 à l’anthologie New Daughters of Africa éditée par Margaret Busby.'],
            ],
