            'occupations' => ['Écrivaine', 'Haute fonctionnaire'],
            'summary' => 'Romancière et haute fonctionnaire ivoirienne née en 1964, Adjoua Flore Kouamé a été la première Ivoirienne directrice de cabinet du vice-président de la République.',
            'blocks' => [
                ['p', 'Adjoua Flore Kouamé, née le 24 novembre 1964 à Abidjan, est une haute fonctionnaire de l’État de Côte d’Ivoire, administratrice civile et membre du corps préfectoral, également romancière de langue française. Diplômée de droit de l’École nationale d’administration de Côte d’Ivoire, elle est préfet hors grade.'],
                ['h2', 'Une carrière dans l’administration'],
                ['p', 'Dans les années 1990, elle devient administratrice civile et membre du bureau du ministère de l’Intérieur, où elle est successivement la première femme ivoirienne chef de cabinet, puis directrice de cabinet du ministre de l’Intérieur de 1991 à 1999. De 2000 à 2003, elle est secrétaire générale de la préfecture d’Abidjan, puis de celle d’Adzopé.'],
                ['p', 'Après un passage au ministère de l’Industrie et du Secteur privé comme cheffe de cabinet, elle est appelée au cabinet du Premier ministre comme conseillère spéciale en 2005, puis devient directrice de cabinet adjointe du Premier ministre jusqu’en 2017. Lorsque Daniel Kablan Duncan accède à la vice-présidence de la République, elle est la première Ivoirienne à occuper les fonctions de directrice de cabinet adjointe, puis de directrice de cabinet du vice-président. Elle assure aussi des vacations de cours à l’ENA d’Abidjan.'],
            ],
            'bibliography' => [
                ['title' => 'Adjoua Flore Kouamé', 'publisher' => 'Wikipédia en français', 'year' => null, 'url' => 'https://fr.wikipedia.org/wiki/Adjoua_Flore_Kouam%C3%A9'],
