            'birthPlace' => 'Bouaké',
            'death' => null,
            'deathPlace' => null,
            'occupations' => ['Écrivaine', 'Universitaire'],
            'summary' => 'Écrivaine et universitaire ivoirienne née en 1968, Michelle Lora est l’autrice de vingt-cinq livres de contes africains pour la jeunesse.',
            'blocks' => [
                ['p', 'Michelle Lora, née le 20 août 1968 à Bouaké, est une écrivaine et universitaire ivoirienne. Ancienne élève du lycée d’excellence Sainte-Marie de Cocody, où elle obtient son baccalauréat en 1987, elle poursuit des études ibériques en France et soutient en 1999 une thèse de doctorat intitulée La dynamique textuelle chez Alberto Insúa.'],
                ['h2', 'L’universitaire et la conteuse'],
                ['p', 'Enseignante-chercheuse à la faculté d’études ibériques et latino-américaines de l’université Félix-Houphouët-Boigny d’Abidjan, elle est maître-assistante et ancienne vice-doyenne chargée de la recherche de 2007 à 2009. Ses recherches portent sur la critique littéraire et génétique, les littératures espagnole et africaine et la communication sociale.'],
                ['p', 'Elle écrit uniquement des nouvelles pour enfants et affirme en 2022 compter vingt-cinq livres de contes africains jeunesse. Elle a mis sur pied une compagnie de conteurs pour enfants et les ateliers « Pathé Pathé ». Première vice-présidente de l’Association des écrivains de Côte d’Ivoire de 2012 à 2015, elle est aussi chroniqueuse radio sous le pseudonyme de « D Love ».'],
            ],
            'bibliography' => [
                ['title' => 'Michelle Lora', 'publisher' => 'Wikipédia en français', 'year' => null, 'url' => 'https://fr.wikipedia.org/wiki/Michelle_Lora'],
            ],
