            'occupations' => ['Écrivaine', 'Ingénieure'],
            'summary' => 'Ingénieure informatique, entrepreneure et écrivaine ivoirienne née vers 1994, Charlette N’Guessan a remporté le prix africain d’innovation en ingénierie 2020.',
            'blocks' => [
                ['p', 'Charlette Désirée N’Guessan, née vers 1994, est une ingénieure informatique, entrepreneure technologique et écrivaine ivoirienne. Elle étudie à la Meltwater Entrepreneurial School of Technology d’Accra, où germe l’idée de son logiciel, et crée en 2018 sa société BACE Group.'],
                ['h2', 'BACE API'],
                ['p', 'Elle devient la première femme à remporter le prix annuel de l’Afrique pour l’innovation en ingénierie décerné par la Royal Academy of Engineering britannique, lors du concours 2020. Elle gagne ce prix grâce à BACE API, une technologie qui permet de vérifier la photo ou la vidéo originale d’une personne prise sur un téléphone portable et d’identifier rapidement la cible. Deux entreprises ghanéennes utilisent le logiciel pour identifier leurs clients.'],
            ],
