            'blocks' => [
                ['p', 'Bouakari Sidiki Koné, dit Tidiss Koné, né le 20 mars 1983 à Odienné, dans le nord-ouest de la Côte d’Ivoire, est un écrivain, enseignant et promoteur culturel ivoirien. Il intègre l’École normale supérieure d’Abidjan, où il obtient un certificat d’aptitude au professorat en lettres modernes et en éducation aux droits de l’homme et à la citoyenneté.'],
                ['h2', 'L’enseignant et le promoteur'],
                ['p', 'Il exerce comme professeur de lettres modernes dans l’enseignement secondaire et occupe parallèlement des fonctions dans l’administration ivoirienne, dans le domaine de la protection juridique et sociale des enfants et adolescents vulnérables. Il s’implique dans la promotion de la littérature et des arts dans le district du Denguélé.'],
                ['p', 'Il est président-fondateur de l’organisation non gouvernementale Citoyens du Livre et des Arts du Denguélé (CILAD) et commissaire général du Festival du livre et des arts du Denguélé (FESTILAD). Il participe à plusieurs manifestations littéraires, dont le Salon international du livre d’Abidjan et le festival Paroles Indigo de Grand-Bassam.'],
