            'summary' => 'Écrivaine, poète et blogueuse ivoirienne née en 1988, Yehni Djidji a fondé l’Agence littéraire Livresque et préside l’Association des blogueurs de Côte d’Ivoire.',
            'blocks' => [
                ['p', 'Fonou N’Guessan Rosine Kakou, dite Yehni Djidji, née à Abidjan en 1988, est une écrivaine, poète et blogueuse ivoirienne. Diplômée en communication, marketing et management, elle est aussi scénariste, chroniqueuse et promotrice de sites internet et d’événements littéraires.'],
                ['h2', 'L’Agence littéraire Livresque'],
                ['p', 'En 2013, elle crée l’Agence littéraire Livresque, spécialisée dans la rédaction, l’édition, la diffusion et la distribution d’œuvres littéraires. Elle est sélectionnée parmi les 35 jeunes innovateurs de moins de 35 ans qui ont fait bouger le monde francophone en 2016 et obtient le premier prix dans la catégorie « Culture et divertissement » grâce à 225nouvelles.com, un site de promotion de la littérature.'],
                ['p', 'En 2017, elle est boursière du programme Mandela Washington Fellowship de la Young African Leaders Initiative. Elle est élue présidente de l’Association des blogueurs de Côte d’Ivoire et reçoit en 2018 le prix Ascom de la communication digitale.'],
            ],
            'bibliography' => [
