            'blocks' => [
                ['p', 'Foua Ernest de Saint-Sauveur, né le 8 novembre 1953 à Alépé, dans le sud de la Côte d’Ivoire, est un écrivain et homme de lettres ivoirien, enseignant de formation. Originaire du Centre-Ouest, du département de Vavoua, il est professeur des CAFOP, les centres chargés de la formation des instituteurs.'],
                ['h2', 'L’animateur de la vie littéraire'],
                ['p', 'Cinquième président de l’Association des écrivains de Côte d’Ivoire, de 2004 à 2011, il en est ensuite président honoraire. Critique littéraire, il anime des émissions littéraires et culturelles sur ONUCI FM, la radio des Nations unies en Côte d’Ivoire, et dirige la publication du magazine culturel Zaouli, qu’il a fondé.'],
                ['p', 'Il est également fondateur et directeur général des Éditions Saint-Sauveur.'],
            ],
            'bibliography' => [
