            'occupations' => ['Écrivain', 'Universitaire'],
            'summary' => 'Philosophe, essayiste et commissaire d’exposition ivoirien né en 1953, Yacouba Konaté a présidé l’Association internationale des critiques d’art.',
            'blocks' => [
                ['p', 'Yacouba Konaté, né le 4 mai 1953 à Katiola, est un philosophe, essayiste et commissaire d’exposition ivoirien. Docteur de troisième cycle et docteur d’État de l’université Paris 1 Panthéon-Sorbonne, il est professeur de philosophie à l’université Félix-Houphouët-Boigny de Cocody, à Abidjan.'],
                ['h2', 'Le critique d’art'],
                ['p', 'Membre de l’Académie des arts, des sciences et des cultures d’Afrique et des diasporas d’Abidjan, il dirige le bureau Afrique de la Fondation Jean-Paul Blanchère. Professeur Fulbright à l’université Stanford en 1998, il enseigne à l’École des hautes études en sciences sociales entre 2004 et 2008, puis à l’université Laval au Canada et à l’université de Floride en 2007.'],
                ['p', 'Il devient en 2008 président de l’Association internationale des critiques d’art (AICA) et est expert du développement culturel pour l’Union européenne. En 2000, il dirige l’Institut national des arts et cultures et le cabinet des ministres de la Culture et de la Francophonie ; il est aussi à la tête de l’Institut national supérieur des arts et de l’action culturelle d’Abidjan.'],
                ['h2', 'Dak’Art et le MASA'],
                ['p', 'Il est l’un des conservateurs des expositions individuelles de la Biennale de Dakar avec Ivo Mesquita et Hans Ulrich Obrist, et en est le directeur artistique en 2006. Depuis 2014, il dirige le Marché des arts du spectacle d’Abidjan (MASA) et, depuis 2009, la Rotonde des arts contemporains dans la galerie Nour-al-Hayat, au Plateau.'],
            ],
            'bibliography' => [
                ['title' => 'Yacouba Konaté', 'publisher' => 'Wikipédia en français', 'year' => null, 'url' => 'https://fr.wikipedia.org/wiki/Yacouba_Konat%C3%A9'],
            ],
        ],
