            'occupations' => ['Écrivaine', 'Enseignante'],
            'summary' => 'Écrivaine ivoirienne née en 1976, Alexis a publié son premier roman en 2015 et siège au bureau de l’Association des écrivains de Côte d’Ivoire.',
            'blocks' => [
                ['p', 'Viviane Kouakou épouse Montéomo, connue sous le nom de plume Alexis, est une écrivaine ivoirienne née le 12 janvier 1976 à Abidjan-Cocody. Enseignante de formation, elle obtient son baccalauréat série D au lycée moderne de Katiola en 1997, puis entre au CAFOP supérieur d’Abidjan en 1999 et décroche un certificat d’aptitude primaire.'],
                ['h2', 'De l’école à l’écriture'],
                ['p', 'Elle enseigne à l’école primaire publique de Pli-Akakro, dans la préfecture de Béoumi, en 2000, puis dans plusieurs localités du centre du pays. De 2012 à 2013, elle est chargée de communication à la direction de l’animation, de la promotion et du suivi des comités de gestion du ministère de l’Éducation nationale.'],
                ['h2', 'Les romans'],
                ['p', 'Son premier roman, Amours, choix et regards, paraît aux Nouvelles Éditions Balafons en mars 2015, suivi de cinq autres œuvres. Membre du bureau exécutif de l’Association des écrivains de Côte d’Ivoire comme trésorière générale puis secrétaire à l’organisation, elle a aussi présidé la section Femme d’Amnesty International Côte d’Ivoire. Depuis novembre 2018, elle dirige une maison d’édition.'],
            ],
            'bibliography' => [
                ['title' => 'Alexis (écrivaine)', 'publisher' => 'Wikipédia en français', 'year' => null, 'url' => 'https://fr.wikipedia.org/wiki/Alexis_(%C3%A9crivaine)'],
