        [
            'slug' => 'celestin-virgile-adiko',
            'name' => 'Célestin-Virgile Adiko',
            'fullName' => 'Célestin-Virgile Adiko Assoi',
            'birth' => '1935',
            'birthPlace' => 'Afféry',
            'death' => '1997',
            'deathPlace' => 'Abidjan',
            'occupations' => ['Écrivain', 'Dramaturge', 'Historien'],
            'summary' => 'Enseignant, diplomate, historien et dramaturge ivoirien (1935-1997), Célestin-Virgile Adiko a présidé l’Association ivoirienne des gens de lettres.',
            'blocks' => [
                ['p', 'Célestin-Virgile Adiko Assoi, né le 24 avril 1935 à Afféry, dans la préfecture d’Adzopé, et mort le 8 juillet 1997 à Abidjan, est un enseignant, diplomate, historien, dramaturge et homme politique ivoirien. Il fréquente les écoles d’Afféry et d’Akoupé, rejoint le collège de Bingerville, obtient son brevet en 1952, puis entre à l’école normale d’instituteurs de Dabou et décroche un baccalauréat scientifique en 1955.'],
                ['h2', 'Le lettré et le diplomate'],
                ['p', 'Il étudie un an à l’École des lettres de Dakar, puis obtient une licence à l’université de Poitiers en 1959, tout en étant professeur adjoint au lycée de Châtellerault. Délégué permanent de la Côte d’Ivoire auprès de l’UNESCO et conseiller culturel à Paris de 1960 à 1961, il enseigne au lycée technique d’Abidjan, travaille comme documentaliste à Vanves, puis au lycée classique d’Abidjan et comme chargé de recherches au ministère de l’Information.'],
                ['h2', 'L’homme de lettres et le politique'],
                ['p', 'Il dirige de 1969 à 1971 l’institution Ouezzin Coulibaly, est député sous le parti unique et membre du Grand Conseil du PDCI. Membre de la Société des auteurs et compositeurs dramatiques et président de l’Association ivoirienne des gens de lettres, il est lauréat du deuxième prix des jeunes auteurs.'],
            ],
            'bibliography' => [
                ['title' => 'Célestin-Virgile Adiko', 'publisher' => 'Wikipédia en français', 'year' => null, 'url' => 'https://fr.wikipedia.org/wiki/C%C3%A9lestin-Virgile_Adiko'],
            ],
        ],
