            'death' => null,
            'deathPlace' => null,
            'occupations' => ['Auteur de bande dessinée', 'Peintre'],
            'summary' => 'Artiste et auteur de bande dessinée ivoirien né vers 1956, Gilbert G. Groud a publié Magie noire chez Albin Michel en 2003.',
            'blocks' => [
                ['p', 'Gnangbei Gilbert, dit Groud G. Gilbert, né vers 1956 à Glacon, dans la sous-préfecture de Toulepleu, est un artiste ivoirien, infographiste, illustrateur, peintre et auteur de bande dessinée. Fils d’un sculpteur et d’une chanteuse, il étudie les arts à l’Institut national des arts d’Abidjan de 1979 à 1986 et prend le pseudonyme de Groud.'],
                ['h2', 'De la publicité à la bande dessinée'],
                ['p', 'En 1982, il remporte le concours « Un timbre contre le tabac » organisé par l’Institut national de santé publique ivoirien. En 1986, il entre à l’agence de publicité Lintas comme maquettiste, puis travaille comme directeur artistique dans différentes agences tout en développant une carrière de peintre.'],
                ['p', 'En 2003, Albin Michel publie son premier album de bande dessinée, Magie noire, consacré à la sorcellerie en Afrique. Un second volume paraît en 2008 chez Vent des savanes.'],
            ],
            'bibliography' => [
                ['title' => 'Gilbert G. Groud', 'publisher' => 'Wikipédia en français', 'year' => null, 'url' => 'https://fr.wikipedia.org/wiki/Gilbert_G._Groud'],
            ],
