        [
            'slug' => 'louis-akin',
            'name' => 'Louis Akin',
            'fullName' => 'Louis Akin',
            'birth' => '1927',
            'birthPlace' => 'Abidjan',
            'death' => '2004',
            'deathPlace' => 'Abidjan',
            'occupations' => ['Écrivain', 'Poète', 'Metteur en scène'],
            'summary' => 'Romancier, poète et homme de théâtre ivoirien (1927-2004), Louis Akin fut en 1953 le premier romancier ivoirien intégralement publié dans une langue européenne.',
            'blocks' => [
                ['p', 'Louis Akin, né le 1er novembre 1927 à Abidjan et mort le 31 mars 2004 dans la même ville, est un romancier, poète, réalisateur, metteur en scène, chorégraphe, opposant politique et militant anticolonialiste ivoirien. Formé en France puis en Allemagne, il s’oppose au résultat du référendum constitutionnel français de septembre 1958 et s’exile volontairement en Guinée.'],
                ['h2', 'Les Ballets africains et le roman'],
                ['p', 'Issu de l’ethnie ébrié, il étudie chez les catholiques de la Mission Saint-Paul du Plateau, puis à l’École primaire supérieure de Bingerville. En 1948, il suit à Paris les cours d’art dramatique de Jean-Marie Serreau au Théâtre de Babylone et fonde en 1950, avec le Guinéen Fodéba Kéïta, les Ballets africains.'],
                ['p', 'Ses romans Bolaô et La Sueur des hommes dénoncent les injustices coloniales ; ils lui valent, malgré la censure, d’être comparé à Ousmane Sembène par la critique allemande et anglophone. Pionnier du roman ivoirien avec Bernard Dadié, Aké Loba, Ahmadou Kourouma et Anoma Kanié, il devient en 1953 le premier romancier ivoirien intégralement publié dans une langue européenne. Bolaô et La Sueur des hommes restent inédits en français, langue dans laquelle il publie deux volumes de poésie, dont un à titre posthume.'],
            ],
            'bibliography' => [
                ['title' => 'Louis Akin', 'publisher' => 'Wikipédia en français', 'year' => null, 'url' => 'https://fr.wikipedia.org/wiki/Louis_Akin'],
            ],
        ],
        [
