            'fullName' => 'Macaire Etty',
            'birth' => '1967',
            'birthPlace' => 'Bocanda',
            'death' => null,
            'deathPlace' => null,
            'occupations' => ['Écrivain', 'Enseignant'],
            'summary' => 'Écrivain et homme de lettres ivoirien né en 1967, Macaire Etty a présidé l’Association des écrivains de Côte d’Ivoire et reçu le Grand Prix Bernard Dadié en 2024.',
            'blocks' => [
                ['p', 'Macaire Etty, né le 5 juillet 1967 à Bocanda, est un écrivain et homme de lettres ivoirien, originaire de Badasso, dans le département de Sikensi. Diplômé de l’École normale supérieure, professeur certifié de lettres modernes, il est promu inspecteur en chef après avoir enseigné deux décennies dans les lycées du pays.'],
                ['h2', 'L’auteur au programme'],
                ['p', 'Ses romans Pour le bonheur des miens et Talouablé, la dévoreuse de livres, ainsi que son œuvre poétique La Geste de Bréké, sont inscrits respectivement en terminale, en sixième et en seconde au programme scolaire ivoirien. Ce poème épique composé en 2016 lui vaut d’être primé dans la catégorie Belles-Lettres à l’édition 2017 des Grands prix des associations littéraires, devenant la première œuvre poétique couronnée dans cette catégorie.'],
                ['h2', 'Le président de l’AECI'],
                ['p', 'Chroniqueur littéraire, éditeur et conférencier, il préside l’Association des écrivains de Côte d’Ivoire de 2016 à 2022. Le 15 mai 2024, lors du Salon international du livre d’Abidjan, il reçoit le Grand Prix Bernard Dadié.'],
            ],
            'bibliography' => [
                ['title' => 'Macaire Etty', 'publisher' => 'Wikipédia en français', 'year' => null, 'url' => 'https://fr.wikipedia.org/wiki/Macaire_Etty'],
            ],
        ],
        [
            'slug' => 'marguerite-abouet',
            'name' => 'Marguerite Abouet',
            'fullName' => 'Patricia N’gbandjui',
            'birth' => '1971',
            'birthPlace' => 'Abidjan',
            'death' => null,
            'deathPlace' => null,
            'occupations' => ['Écrivaine', 'Scénariste'],
            'summary' => 'Écrivaine et scénariste franco-ivoirienne née en 1971, Marguerite Abouet est l’autrice de la bande dessinée Aya de Yopougon, primée à Angoulême en 2006.',
            'blocks' => [
                ['p', 'Marguerite Abouet, nom de plume de Patricia N’gbandjui, née en 1971 à Abidjan, est une écrivaine, scénariste et réalisatrice franco-ivoirienne. Elle est la fille d’une mère directrice chez Singer et d’un père cadre chez Hitachi, et passe douze ans de sa vie à Yopougon, quartier populaire d’Abidjan dont elle s’inspirera pour ses scénarios.'],
                ['h2', 'Aya de Yopougon'],
                ['p', 'Arrivée en France à l’âge de douze ans, elle s’intéresse à l’écriture de scénarios de bande dessinée après avoir lu les œuvres de Marjane Satrapi. Le premier tome d’Aya de Yopougon, dessiné par Clément Oubrerie, reçoit le prix du premier album au festival d’Angoulême en 2006 et devient un succès commercial.'],
                ['p', 'Elle poursuit la série et crée Akissi, dont les bêtises de l’héroïne sont directement inspirées de sa propre enfance.'],
            ],
            'bibliography' => [
                ['title' => 'Marguerite Abouet', 'publisher' => 'Wikipédia en français', 'year' => null, 'url' => 'https://fr.wikipedia.org/wiki/Marguerite_Abouet'],
            ],
        ],
        [
            'slug' => 'noel-x-ebony',
            'name' => 'Noël X. Ebony',
            'fullName' => 'Noël Essy Kouamé',
            'birth' => '1953',
            'birthPlace' => 'Koun-Fao',
            'death' => '1986',
            'deathPlace' => 'Dakar (Sénégal)',
            'occupations' => ['Journaliste', 'Écrivain'],
            'summary' => 'Journaliste et écrivain ivoirien (1953-1986), Noël X. Ebony est l’auteur de Déjà Vu et a donné son nom au prix du meilleur journaliste ivoirien.',
            'blocks' => [
                ['p', 'Noël X. Ebony, de son vrai nom Noël Essy Kouamé, né en 1953 à Koun-Fao et mort le 22 juillet 1986 à Dakar, est un journaliste, poète, romancier, dramaturge, essayiste et critique d’art ivoirien. Collaborateur de Fraternité Matin, correspondant ouest-africain du mensuel Demain l’Afrique, il était à sa mort rédacteur en chef du mensuel Africa International.'],
                ['h2', 'Le journaliste et l’écrivain'],
                ['p', 'Journaliste éclectique, il aborde la politique, la culture et surtout la musique, et tient une chronique en français populaire abidjanais dans Ivoire Dimanche. Il est l’auteur de Déjà Vu, publié en 1983 à Paris par l’éditrice américaine Nidra Poller : le texte, au style novateur, est considéré par plusieurs critiques comme un classique de la littérature africaine contemporaine, Lilyan Kesteloot voyant en lui « le Soyinka de l’Afrique francophone ». Il est réédité en 2010 chez L’Harmattan.'],
                ['p', 'Sa mort prématurée dans un accident de la circulation, aux circonstances mal définies, a freiné la diffusion d’une partie de son œuvre, restée inédite. Le prix Noël X. Ebony, créé par l’Union nationale des journalistes de Côte d’Ivoire, récompense le meilleur journaliste du pays.'],
            ],
            'bibliography' => [
                ['title' => 'Noël X. Ebony', 'publisher' => 'Wikipédia en français', 'year' => null, 'url' => 'https://fr.wikipedia.org/wiki/No%C3%ABl_X._Ebony'],
            ],
        ],
