            'blocks' => [
                ['p', 'Paul Adiapa Ahizi, né le 14 mars 1941 à Treichville, à Abidjan, est un chercheur en agronomie, spécialiste de la génétique du palmier à huile, et un poète ivoirien.'],
                ['h2', 'L’Association des écrivains'],
                ['p', 'Il fonde l’Union des poètes et écrivains ivoiriens, qui fusionne l’année suivante avec l’Association des poètes de Côte d’Ivoire pour former l’Association des écrivains de Côte d’Ivoire. Cofondateur de l’AECI avec Jean-Marie Adiaffi, il en est le premier président, de 1987 à 1991.'],
