            'deathPlace' => null,
            'occupations' => ['Écrivain', 'Homme politique'],
            'summary' => 'Intellectuel, homme d’affaires et écrivain ivoirien né en 1908, Tidiane Dem a été député et secrétaire d’État à l’Élevage.',
            'blocks' => [
                ['p', 'Tidiane Dem, né le 8 juin 1908 à Niakaramandougou, est un intellectuel, homme d’affaires, homme politique et écrivain ivoirien. Descendant de Peuls du Sénégal par son père et de Sénoufo par sa mère, il est élevé dans ces traditions et consigne par écrit les récits que lui transmet son père.'],
                ['h2', 'Le commerçant et l’élu'],
                ['p', 'Riche commerçant à Korhogo et animateur du jeune Syndicat des commerçants, il est élu député à l’Assemblée nationale constituante après la Seconde Guerre mondiale. Il rejoint ensuite le PDCI, devient conseiller territorial de Korhogo, député de la Première République, secrétaire d’État à l’Élevage, puis ministre provisoire de l’Agriculture et de la Coopération.'],
            ],
