            'blocks' => [
                ['p', 'Joseph N’cho Anouma, dit Joseph Anouma, né en 1949 à Dabré, dans la sous-préfecture de M’Batto, est un poète et plasticien ivoirien. En plus de son œuvre écrite, il donne des cours de peinture, de sculpture, de gravure, de céramique, de dessin et de graphisme à l’Institut national supérieur des arts et de l’action culturelle d’Abidjan, où il est professeur certifié d’arts plastiques.'],
                ['h2', 'L’art et la revue'],
                ['p', 'Il a été directeur de l’École des beaux-arts et collabore à la revue artistique L’École des arts. Il a notamment présenté l’exposition « La renaissance », consacrée à la transhumance, aux regrets, à la sagesse, à l’introspection et aux génies de la nature.'],
            ],
