            'death' => null,
            'deathPlace' => null,
            'occupations' => ['Écrivain'],
            'summary' => 'Écrivain ivoirien né en 2001, Nincemon Fallé a été révélé par Ces soleils ardents, lauréat du Prix Voix d’Afriques en 2024.',
            'blocks' => [
                ['p', 'Nincemon Fallé, de son nom complet Fallé Nincemon Anselme Junior Michel, né le 19 septembre 2001 à Bondoukou, est un écrivain ivoirien. Originaire de l’est du pays, il grandit entre Abidjan, Aboisso et Daloa.'],
                ['h2', 'Ces soleils ardents'],
                ['p', 'Après une formation en communication visuelle et un BTS, il étudie les lettres modernes à l’université Félix-Houphouët-Boigny et travaille comme graphiste et directeur artistique dans une agence de communication. Son premier roman, Ces soleils ardents, paraît en 2024 aux éditions JC Lattès et reçoit le Prix Voix d’Afriques. Il y met en scène deux étudiants, Iro et Thierry, dans le milieu universitaire ivoirien, et aborde la précarité étudiante, les inégalités sociales, l’amitié et la résilience.'],
                ['p', 'Il travaille en parallèle à une trilogie de fantasy intitulée Etiofari, inspirée des cultures et des imaginaires africains.'],
            ],
            'bibliography' => [
                ['title' => 'Nincemon Fallé', 'publisher' => 'Wikipédia en français', 'year' => null, 'url' => 'https://fr.wikipedia.org/wiki/Nincemon_Fall%C3%A9'],
            ],
