            'birthPlace' => 'Daloa',
            'death' => null,
            'deathPlace' => null,
            'occupations' => ['Écrivain', 'Plasticien', 'Universitaire'],
            'summary' => 'Plasticien, romancier et universitaire ivoirien né en 1971, Célestin Koffi Yao a fondé le centre culturel Sankonian à Abobo.',
            'blocks' => [
                ['p', 'Célestin Koffi Yao, né le 6 avril 1971 à Daloa, est un artiste plasticien et universitaire ivoirien, figure contemporaine de la sculpture, également romancier, documentariste, essayiste et galeriste. Il est vice-président du Comité national ivoirien Mémoire du monde et membre du bureau exécutif du comité régional africain du programme Mémoire du monde.'],
                ['h2', 'La galerie et le centre Sankonian'],
                ['p', 'Il ouvre la Galerie Koffi-Yao en 2013 à Cocody, y expose quatorze artistes, puis la ferme en 2016 pour un projet plus vaste. Il fonde alors à Abobo, dans le secteur « Derrière-rails », le Centre pour la culture, les arts et le savoir – Sankonian, qui comporte une galerie, une résidence artistique, une médiathèque, un théâtre et un café littéraire.'],
                ['p', 'Son art s’inspire de l’image du noir et de sa terre matrice, et s’ancre dans la vie contemporaine et le quotidien. Ses documentaires défendent la préservation du patrimoine culturel matériel et immatériel africain.'],
            ],
            'bibliography' => [
                ['title' => 'Célestin Koffi Yao', 'publisher' => 'Wikipédia en français', 'year' => null, 'url' => 'https://fr.wikipedia.org/wiki/C%C3%A9lestin_Koffi_Yao'],
            ],
        ],
