            'death' => null,
            'deathPlace' => null,
            'occupations' => ['Écrivain', 'Poète'],
            'summary' => 'Poète-slameur ivoirien né en 1991, Nin’wlou Ariel Ménélik préside la Fédération ivoirienne de slam poésie et a publié La Marche du Feu.',
            'blocks' => [
                ['p', 'Lao Lionel Alex, dit Nin’wlou Ariel Ménélik, né le 13 novembre 1991 à Abidjan-Yopougon, est un écrivain et poète-slameur ivoirien. Son nom d’artiste signifie « Paroles de Feu » en wê, une langue de l’ouest du pays. Titulaire d’une maîtrise en droit privé, il est aussi instructeur en prise de parole.'],
                ['h2', 'L’École des poètes et les prix'],
                ['p', 'En 2015, il préside l’École des poètes de Côte d’Ivoire, l’un des plus grands mouvements de poésie et de slam du pays. Il remporte en 2017 le prix Kailcedra du meilleur slameur, puis le concours Lydia Ludic Talents 2021 organisé par l’Union des journalistes culturels de Côte d’Ivoire. En 2022, il reçoit le troisième prix du concours de slam Libres ensemble dans le cadre des Jeux de la francophonie et le trophée du meilleur slameur au Prix international des musiques urbaines et du coupé-décalé.'],
                ['p', 'Il présente en mai 2021 à l’Institut français de Côte d’Ivoire le spectacle « La Marche du Feu », qui devient son premier livre, paru en septembre 2021 aux Éditions Zadié.'],
            ],
            'bibliography' => [
                ['title' => 'Nin’wlou Ariel Ménélik', 'publisher' => 'Wikipédia en français', 'year' => null, 'url' => 'https://fr.wikipedia.org/wiki/Nin%E2%80%99wlou_Ariel_M%C3%A9n%C3%A9lik'],
            ],
        ],
        [
            'slug' => 'alafe-wakili',
            'name' => 'Alafé Wakili',
            'fullName' => 'Assé Alafé Wakili',
            'birth' => '1971',
            'birthPlace' => 'Agboville',
            'death' => null,
            'deathPlace' => null,
            'occupations' => ['Journaliste', 'Écrivain'],
            'summary' => 'Journaliste et écrivain ivoirien né en 1971, Alafé Wakili a fondé en 2003 L’Intelligent d’Abidjan, dont il est le directeur de publication.',
            'blocks' => [
                ['p', 'Assé Alafé Wakili, né le 9 juillet 1971 à Agboville, est un journaliste, écrivain et activiste ivoirien. Après ses études primaires et secondaires dans sa ville natale, il obtient un DEUG et une licence de philosophie à l’université Félix-Houphouët-Boigny d’Abidjan. Il adhère à la FESCI et fonde l’Union des jeunes journalistes de Côte d’Ivoire, dont il est vice-président.'],
                ['h2', 'De la presse à L’Intelligent d’Abidjan'],
                ['p', 'Sa carrière commence au milieu des années 1990 dans la presse écrite, au Réveil Hebdo, au Démocrate et à La Nouvelle République. En septembre 2003, alors que le pays est coupé en deux par la crise, il crée le quotidien L’Intelligent d’Abidjan, qu’il dirige et dont il est le directeur de publication ; il préside aussi le conseil d’administration de Totem Holding. En 2006, il devient conseiller technique au ministère de la Communication, fonction qu’il quitte en avril 2007.'],
                ['p', 'En juillet 2026, il soutient à l’université Félix-Houphouët-Boigny un master en sciences de l’information et de la communication, avec un mémoire intitulé La stratégie éditoriale comme outil de management de l’entreprise de presse.'],
                ['h2', 'Livres et distinctions'],
                ['p', 'Il est l’auteur d’Instant de vie (2009), de Notre histoire avec Laurent Gbagbo (L’Harmattan, 2013) et de Championne l’enjailleuse (2016). Il reçoit en 2007 le prix panafricain du meilleur patron de la presse privée d’Afrique de l’Ouest, en 2014 le prix du meilleur journaliste ouest-africain à Paris, puis en 2020 le trophée d’excellence de la compétitivité dans le secteur des médias. Père de quatre enfants, il a épousé l’animatrice de télévision Tata Nahomi en octobre 2010.'],
            ],
            'bibliography' => [
                ['title' => 'Alafé Wakili', 'publisher' => 'Wikipédia en français', 'year' => null, 'url' => 'https://fr.wikipedia.org/wiki/Alaf%C3%A9_Wakili'],
            ],
        ],
        [
            'slug' => 'marie-laure-n-goran',
            'name' => 'Marie-Laure N’Goran',
            'fullName' => 'Marie-Laure N’Goran',
            'birth' => null,
            'birthPlace' => 'Côte d’Ivoire',
            'death' => null,
            'deathPlace' => null,
            'occupations' => ['Journaliste', 'Écrivaine'],
            'summary' => 'Journaliste et présentatrice ivoirienne, Marie-Laure N’Goran préside depuis 2026 l’Union nationale des journalistes de Côte d’Ivoire et a publié un roman en 2023.',
            'blocks' => [
                ['p', 'Marie-Laure N’Goran, née un 6 août, est une journaliste et présentatrice à la Radiodiffusion télévision ivoirienne (RTI). Diplômée de l’Institut des sciences et techniques de la communication et de l’université Alassane-Ouattara de Bouaké en sciences juridiques, administratives et de gestion, elle travaille à l’Organisation des Nations unies pour l’alimentation et l’agriculture de 2004 à 2011.'],
                ['h2', 'De la télévision au roman'],
                ['p', 'Recrutée en 2011 par la RTI, elle présente d’abord le journal de 23 heures, puis celui de 20 heures à partir de 2013. Elle publie en 2023 un roman intitulé Le combat d’une héroïne, et si c’était une histoire vraie…, présenté au Sofitel Hôtel Ivoire sous le parrainage de la ministre Mariatou Koné'],
                ['p', 'Elle est élue le 7 juin 2026 présidente de l’Union nationale des journalistes de Côte d’Ivoire, devenant la première femme à occuper cette fonction. Fille de la chanteuse Lou Suzanne Nazou, épouse du pasteur N’Goran Isidore et mère de trois garçons, elle est nommée chevalier de l’ordre du mérite culturel en 2012, reçoit le prix Ebony de la meilleure présentatrice de 2015 à 2017 et le prix africain du développement de 2016 à 2018, puis est nommée chevalier de l’ordre national en 2017, chevalier de l’ordre de la communication et officier de l’ordre de la solidarité et de la Paix en 2020. Le 3 août 2026, elle reçoit le prix national d’excellence pour le développement des médias.'],
            ],
            'bibliography' => [
                ['title' => 'Marie-Laure N’Goran', 'publisher' => 'Wikipédia en français', 'year' => null, 'url' => 'https://fr.wikipedia.org/wiki/Marie-Laure_N%27Goran'],
            ],
