            'summary' => 'Rugbyman né à Abidjan en 1981, Thierry Dusautoir a été capitaine du XV de France et élu meilleur joueur du monde en 2011.',
            'blocks' => [
                ['p', 'Thierry Dusautoir, né le 18 novembre 1981 à Abidjan, est un joueur international français de rugby à XV, né d’un père français et d’une mère ivoirienne et détenteur des deux nationalités. Il évolue au poste de troisième ligne aile.'],
                ['h2', 'Les clubs'],
                ['p', 'Il commence en championnat de France avec le CA Bègles-Bordeaux, rejoint l’US Colomiers puis le Biarritz olympique, avec lequel il remporte deux titres de champion de France en 2005 et 2006. En 2006, il rejoint le Stade toulousain, où il gagne trois nouveaux titres de champion en 2008, 2011 et 2012 et la Coupe d’Europe en 2010.'],
                ['h2', 'Le XV de France'],
                ['p', 'Il obtient 80 sélections avec l’équipe de France, dont il détient le record de capitanats avec 56, participe au Grand Chelem 2010 et à la finale de la Coupe du monde 2011. Élu meilleur joueur du monde par l’International Rugby Board en 2011, il est introduit au Temple de la renommée World Rugby en 2023 et détient le record de plaquages en un match, avec 38 contre la Nouvelle-Zélande en 2007.'],
