                ['p', 'Evan Ndicka, né le 20 août 1999 à Paris, est un footballeur international ivoirien qui évolue au poste de défenseur central. D’origine camerounaise par son père et ivoirienne par sa mère, il commence le football en 2006 au F.C.A. Paris 19e, puis rejoint à 13 ans le centre de formation de l’AJ Auxerre, où il signe son premier contrat professionnel le 5 février 2017.'],
