                ['h2', 'Les Éléphants'],
                ['p', 'Il honore sa première sélection avec la Côte d’Ivoire le 9 septembre 2023 contre le Lesotho, au stade Laurent Pokou de San Pedro. Il est ensuite retenu dans le groupe ivoirien pour la CAN 2023, remportée à domicile par les Éléphants.'],
