            'blocks' => [
                ['p', 'Simon Adingra, né le 1er janvier 2002 à Yamoussoukro, est un footballeur international ivoirien qui évolue au poste d’ailier gauche. Enfant, ses parents sont victimes d’une escroquerie : un homme se présentant comme entraîneur leur promet un centre de formation au Bénin contre 300 dollars. Adingra et neuf de ses amis se retrouvent livrés à eux-mêmes et enchaînent les petits boulots avant de rejoindre l’académie Right to Dream, au Ghana.'],
                ['h2', 'Nordsjælland et Brighton'],
                ['p', 'Il rejoint en janvier 2020 le FC Nordsjælland, club partenaire de son académie, au Danemark, où une fracture retarde ses débuts. Le 24 juin 2022, il s’engage pour quatre ans avec Brighton & Hove Albion, qui le prête aussitôt une saison à l’Union saint-gilloise. Il est ensuite prêté à l’AS Monaco en février 2026.'],
                ['h2', 'Héros de la CAN 2023'],
                ['p', 'Le 11 février 2024, il remporte la CAN 2023 à domicile avec la Côte d’Ivoire, au stade Alassane-Ouattara d’Ébimpé. Auteur de deux passes décisives en finale, il est élu meilleur joueur de la rencontre et meilleur jeune joueur de la compétition.'],
