                ['p', 'Le 27 octobre 2019, il joue son premier match professionnel en Serie A face à l’Udinese et marque lors de la victoire 7 à 1, devenant le premier joueur né en 2002 à inscrire un but dans l’élite italienne. Connu à ses débuts sous le nom d’Amad Traoré, il opte pour Amad Diallo en juillet 2020. Manchester United annonce son arrivée en octobre 2020 ; il rejoint officiellement le club le 7 janvier 2021, pour une indemnité estimée à 25 millions d’euros plus 15 de bonus. Il est ensuite prêté aux Rangers FC puis à Sunderland.'],
                ['h2', 'Les Éléphants'],
                ['p', 'Il honore sa première sélection le 26 mars 2021 contre le Niger, lors des éliminatoires de la CAN 2021, et figure dans la liste ivoirienne pour la CAN 2025.'],
