            'blocks' => [
                ['p', 'Jérémie Boga, né le 3 janvier 1997 à Marseille, est un footballeur international ivoirien qui possède également la nationalité française. Issu d’une famille originaire de Côte d’Ivoire, il commence le football à cinq ans à l’ASPTT Marseille, puis rejoint Chelsea en 2008. En 2015, il remporte l’UEFA Youth League avec les Blues face au Chakhtar Donetsk, étant impliqué dans les trois buts de son équipe.'],
