                ['h2', 'Atalanta, Nice et la Juventus'],
                ['p', 'Le 24 janvier 2022, il rejoint l’Atalanta Bergame, puis l’OGC Nice le 25 juillet 2023. Le 1er février 2026, Nice le prête à la Juventus avec une option d’achat d’environ cinq millions d’euros. International ivoirien depuis le 10 juin 2017 et un match contre la Guinée, il participe aux CAN 2021 et 2023, la seconde remportée par les Éléphants.'],
