            'blocks' => [
                ['p', 'Emmanuel Agbadou, né le 17 juin 1997 à Abidjan, est un footballeur international ivoirien qui évolue au poste de défenseur central. Fils d’un ancien footballeur du Stade d’Abidjan, il commence à l’académie Don Koff, soutenu par sa mère alors que son père ne souhaite pas le voir embrasser une carrière de joueur. Il passe par l’Académie Alloka Sahoure et l’Africa Sports avant de rejoindre le FC San-Pédro en 2017.'],
