                ['h2', 'Wolverhampton, Beşiktaş et les Éléphants'],
                ['p', 'Le 9 janvier 2025, il quitte Reims pour Wolverhampton, puis s’engage avec Beşiktaş le 6 février 2026 pour 18 millions d’euros, jusqu’en 2030. Il honore sa première sélection ivoirienne le 8 octobre 2021 contre le Malawi et participe avec les Éléphants à la Coupe du monde 2026.'],
