            'blocks' => [
                ['p', 'Sinaly Diomandé, né le 9 avril 2001 à Yopougon, est un footballeur international ivoirien qui évolue au poste de défenseur central. Formé à l’académie Jean-Marc Guillou à Abidjan, il rejoint ensuite le Guidars FC, au Mali. Le 2 septembre 2019, il signe son premier contrat professionnel de quatre saisons à l’Olympique lyonnais, qui débourse 0,55 million d’euros pour le recruter.'],
