                ['p', 'Il intègre d’abord l’équipe réserve, avec laquelle il dispute seize matchs de National 2 et six de Youth League. Il fait ses débuts en Ligue 1 le 18 septembre 2020, à 19 ans, en remplaçant Léo Dubois face à Nîmes. Le 30 août 2024, il signe librement à l’AJ Auxerre jusqu’en juin 2027.'],
                ['h2', 'Les Éléphants'],
                ['p', 'Il dispute son premier match avec la Côte d’Ivoire le 8 octobre 2020 face à la Belgique, puis son premier match officiel le 17 novembre 2020 contre Madagascar, en qualifications pour la CAN 2021.'],
