                ['p', 'Seydou Doumbia, né le 31 décembre 1987 à Abidjan, est un footballeur international ivoirien qui évolue au poste d’attaquant. Il fait ses premières armes au Centre de formation d’Inter FC dès 1999, puis rejoint l’Athlétic Adjamé en 2003, avant des prêts au Toumodi FC et à l’AS Denguélé. Avec ce dernier club, il est meilleur buteur du championnat ivoirien en 2005, avec 15 buts en 20 matchs.'],
                ['h2', 'Le Japon, la Suisse et le CSKA'],
                ['p', 'Repéré par Kashiwa Reysol, il part au Japon en 2006 et passe par Tokushima Vortis avant de rejoindre les Young Boys Berne en 2008. Il y inscrit 42 buts en deux saisons et termine meilleur buteur du championnat suisse en 2008-2009 puis en 2009-2010. Avec le CSKA Moscou, il établit le record de buts marqués en une saison de Premier-Liga russe, avec 28 réalisations en 2011-2012.'],
                ['h2', 'Les Éléphants'],
                ['p', 'Il est retenu pour la CAN 2012, manque l’édition 2013 à cause d’une grave blessure au dos, puis est sélectionné pour la CAN 2015.'],
            ],
            'bibliography' => [
