                ['p', 'Kanga Gauthier Akalé, né le 7 mars 1981 à Abidjan, est un footballeur international ivoirien qui occupe le poste de milieu offensif. Formé au Stella Club d’Adjamé, il s’exile en Suisse en 1998, à 17 ans, à Sion, puis rejoint le FC Zurich, où il réalise deux dernières saisons pleines. Il est appelé en sélection ivoirienne par Robert Nouzaret, mais ne connaît sa première cape qu’en février 2003, contre le Cameroun.'],
