            'blocks' => [
                ['p', 'Bonaventure Kalou, né le 12 janvier 1978 à Oumé, est un footballeur international ivoirien qui évoluait au poste d’attaquant. Il est le frère aîné de Salomon Kalou. Il se fait remarquer aux Pays-Bas, au Feyenoord Rotterdam, avec lequel il remporte la Coupe de l’UEFA en 2002.'],
                ['h2', 'Auxerre et le PSG'],
                ['p', 'Il est ensuite découvert en France lors de son passage à l’AJ Auxerre, où il gagne la Coupe de France en 2005 juste avant de s’engager au Paris Saint-Germain. Pour son premier match officiel avec Paris, le 5 août 2005 contre le FC Metz, il délivre trois passes décisives et marque un but. En fin de saison, il inscrit l’un des deux buts du PSG en finale de la Coupe de France face à l’Olympique de Marseille, remportée 2 à 1.'],
                ['h2', 'Lens et Vavoua'],
                ['p', 'Fin juillet 2007, il rejoint le RC Lens pour 1,5 million d’euros et retrouve Guy Roux. En octobre 2018, il est élu maire de Vavoua, ville du centre de la Côte d’Ivoire.'],
