            'blocks' => [
                ['p', 'Gilles Yapi-Yapo, né le 30 janvier 1982 à Abidjan, est un ancien footballeur international ivoirien devenu entraîneur. Formé à l’ASEC Mimosas, il joue ensuite au KSK Beveren, au FC Nantes, aux Young Boys de Berne et au FC Bâle. Il évolue en 2013 au Dubaï Club, puis retourne en Suisse, au FC Zurich.'],
                ['h2', 'Les titres suisses'],
