                ['p', 'Joël Tiéhi, né le 12 juin 1964 à Abidjan, est un ancien footballeur international ivoirien qui évoluait au poste d’attaquant. Formé au Stade d’Abidjan, il rejoint ensuite la France et joue notamment au Havre AC, où il dispute son premier match de Division 1 le 28 novembre 1987, face à Monaco.'],
                ['h2', 'Le Havre, Lens et l’étranger'],
