            'summary' => 'Avant-centre international ivoirien né en 2003, Oumar Diakité a inscrit le but de la qualification des Éléphants face au Mali en quart de finale de la CAN 2023.',
            'blocks' => [
                ['p', 'Oumar Diakité, né le 20 décembre 2003 à Bingerville, est un footballeur international ivoirien qui évolue au poste d’avant-centre. Formé à l’ASEC Mimosas, il rejoint l’Autriche et le RB Salzbourg le 12 janvier 2022, avec un contrat jusqu’en juin 2026, et est envoyé à l’équipe partenaire du FC Liefering. Il y marque son premier but le 3 avril 2022 face à l’équipe B du Rapid Vienne, puis signe son premier doublé le 15 avril contre le FC Dornbirn.'],
                ['h2', 'Le Stade de Reims'],
                ['p', 'Lors de l’été 2023, il rejoint le Stade de Reims pour cinq saisons, jusqu’en juin 2028. Il inscrit son premier but avec le club champenois le 3 septembre 2023 face au FC Metz, puis égalise contre le Paris SG le 10 mars 2024, lors d’un match nul 2 à 2.'],
                ['h2', 'Le but du Mali'],
                ['p', 'Retenu pour la CAN 2023, il marque en quart de finale face au Mali, à la 121e minute, offrant la victoire 2 à 1 aux Éléphants au stade de la Paix de Bouaké. La Côte d’Ivoire remporte ensuite la compétition. Il est prêté au SK Sturm Graz par le Stade de Reims.'],
            ],
