                ['p', 'Nina Kpaho, née le 30 décembre 1996, est une footballeuse internationale ivoirienne qui évolue au poste de défenseur. Elle participe avec la sélection ivoirienne à la Coupe du monde 2015 organisée au Canada, le tout premier Mondial de l’équipe féminine du pays.'],
