                ['p', 'Lors du tournoi, elle joue un match, contre l’Allemagne, le 7 juin 2015 au stade TD Place d’Ottawa, perdu 10 à 0. Titularisée, elle est remplacée par Fernande Tchétché après 38 minutes de jeu.'],
            ],
