                ['p', 'Seydou Gbané, né le 12 avril 1992 en Côte d’Ivoire, est un taekwondoïste ivoirien. Il est le frère des taekwondoïstes Abdoulaye et Hamza Gbané. Il remporte la médaille de bronze des moins de 87 kg aux Jeux africains de 2015 à Brazzaville, puis l’or dans la même catégorie aux Jeux africains de 2019 à Rabat.'],
