                ['p', 'Firmin Zokou, né le 9 mars 1984, est un taekwondoïste ivoirien. Au cours de sa carrière, il remporte quatre titres mondiaux dans différentes organisations, dont deux Coupes du monde francophones, en 2011 au Bénin et en 2013 en Côte d’Ivoire. Il est médaillé d’or des plus de 87 kg aux Jeux africains de 2011 à Maputo et de bronze aux Jeux africains de 2015 à Brazzaville.'],
                ['h2', 'Le vice-champion du monde'],
                ['p', 'Aux Championnats du monde 2015 de Tcheliabinsk, il obtient la médaille d’argent des plus de 87 kg, après une cinquième place en 2013 à Puebla. Il est également médaillé de bronze aux Championnats d’Afrique 2010 et 2018, champion d’Afrique police et militaire en 2019, et champion d’Europe Masters en 2023, puis champion de France Masters en 2024 et 2025.'],
                ['h2', 'Après les tatamis'],
                ['p', 'Parallèlement à sa carrière, il exerce comme instructeur de self-défense et préparateur mental certifié, spécialisé dans la préparation à la performance. Il intervient comme conférencier en France, en Côte d’Ivoire et en Allemagne, notamment auprès de Vestiaire Collective, Dior, du Grand Palais et de l’UNESCO.'],
