            'summary' => 'Sprinteur ivoirien né en 1954, Avognan Nogboum a été porte-drapeau aux Jeux de Los Angeles et médaillé d’argent du relais 4 × 100 m à l’Universiade.',
            'blocks' => [
                ['p', 'Avognan Nogboum, né en 1954 en Côte d’Ivoire, est un ancien sprinteur ivoirien. Il participe à ses premiers Jeux olympiques en 1976, à Montréal, où il est éliminé dès les qualifications du 400 mètres.'],
                ['h2', 'Les relais'],
                ['p', 'Lors de l’Universiade, il établit un record personnel sur 400 mètres en 46 s 25 et remporte avec le relais 4 × 100 mètres la médaille d’argent, en établissant un record d’Afrique en finale avec 38 s 73. Aux Championnats du monde d’Helsinki en 1983, il court dans les relais 4 × 100 et 4 × 400 mètres, éliminés en qualifications. Aux Jeux de Los Angeles, en 1984, il est porte-drapeau de la Côte d’Ivoire et termine sixième en demi-finale du relais 4 × 400 mètres avec Kablan Degnan, René Djédjémel Mélédjé et Gabriel Tiacoh, après un record national de 3 min 3 s 50 en séries. Il est également médaillé d’or du championnat national ivoirien.'],
            ],
            'bibliography' => [
                ['title' => 'Avognan Nogboum', 'publisher' => 'Wikipédia en français', 'year' => null, 'url' => 'https://fr.wikipedia.org/wiki/Avognan_Nogboum'],
