            'blocks' => [
                ['p', 'Franck Waota, né le 6 décembre 1971, est un ancien sprinteur ivoirien spécialisé dans le 200 mètres. Il représente la Côte d’Ivoire aux Jeux olympiques de 1992 à Barcelone et de 1996 à Atlanta, ainsi qu’aux Championnats du monde d’athlétisme de 1993. Il est finaliste du relais 4 × 100 mètres aux Jeux de 1992 et aux Mondiaux de 1993, où il termine septième avec Ouattara Lagazane, Jean-Olivier Zirignon et Ibrahim Meité. Le même quatuor remporte la médaille d’argent aux Jeux de la Francophonie de 1994.'],
                ['h2', 'Records et titre'],
