            'summary' => 'Gardien international ivoirien né en 1979, Boubacar Barry Copa a remporté la CAN 2015 et disputé trois Coupes du monde.',
            'blocks' => [
                ['p', 'Boubacar Barry Copa, né le 30 décembre 1979 à Marcory, est un ancien gardien de but international ivoirien, devenu entraîneur des gardiens. Issu d’une famille guinéenne peule de Dalaba, il commence par jouer dans les rues d’Abidjan et intègre les cadets du Stella Club d’Adjamé comme milieu de terrain. Le 1er août 1995, il est accepté comme gardien à l’académie MimoSifcom grâce à Jean-Marc Guillou, qui lui fait signer son premier contrat professionnel avec l’ASEC Mimosas en 1999.'],
                ['h2', 'Rennes, Beveren et Lokeren'],
                ['p', 'En novembre 2000, il signe au Stade rennais, où il côtoie Bernard Lama et Petr Čech, puis rejoint en 2003 le KSK Beveren, dont il devient titulaire. Le club belge atteint la finale de la Coupe de Belgique en 2004 et se qualifie pour la Ligue des champions. En juillet 2007, il s’engage pour trois ans avec le Sporting Lokeren, avec lequel il remporte la Coupe de Belgique en 2012. Il y marque même un but sur penalty le 3 mars 2012, contre Westerlo. Il quitte le club en mai 2017, après dix ans.'],
                ['h2', 'Les Éléphants'],
                ['p', 'Il honore sa première sélection le 18 juin 2000, contre la Tunisie, et compte 86 sélections. Il est finaliste de la CAN en 2006 et 2012, année où il n’encaisse aucun but du tournoi avant la défaite en finale contre la Zambie aux tirs au but, puis vainqueur de l’édition 2015. Il participe aux Coupes du monde 2006, 2010 et 2014.'],
            ],
            'bibliography' => [
                ['title' => 'Boubacar Barry Copa', 'publisher' => 'Wikipédia en français', 'year' => null, 'url' => 'https://fr.wikipedia.org/wiki/Boubacar_Barry_Copa'],
            ],
        ],
