            'deathPlace' => null,
            'occupations' => ['Footballeur'],
            'summary' => 'Défenseur international ivoirien né en 1983, Arthur Boka a été champion d’Allemagne 2007 avec Stuttgart et finaliste de la CAN en 2006 et 2012.',
            'blocks' => [
                ['p', 'Arthur Boka, né le 2 avril 1983 à Abidjan, est un footballeur international ivoirien qui évolue au poste de défenseur. Formé à l’Académie Mimosifcom de l’ASEC Mimosas, il rejoint l’Europe en 2002, au KSK Beveren, en Belgique. Avec le club flamand, il participe au parcours qui mène l’équipe jusqu’en finale de la Coupe de Belgique en 2004.'],
                ['h2', 'Strasbourg, Stuttgart et Málaga'],
                ['p', 'En 2004, il signe au RC Strasbourg, en Ligue 1, et remporte la Coupe de la Ligue en 2005, son premier trophée majeur, avant la relégation du club en Ligue 2 en 2006. Il rejoint ensuite le VfB Stuttgart, où il reste huit saisons et devient champion d’Allemagne en 2007, devant Schalke 04. Il atteint également les finales de la Coupe d’Allemagne en 2007 et 2013 et dispute la Ligue des champions et la Ligue Europa. En juillet 2014, il rejoint le Málaga CF, en Liga.'],
                ['h2', 'Les Éléphants'],
                ['p', 'Il connaît sa première sélection avec la Côte d’Ivoire en 2004 et compte 83 sélections et un but jusqu’en 2015. Il est finaliste de la CAN en 2006 face à l’Égypte, puis en 2012 contre la Zambie, les deux finales étant perdues. Il participe aussi aux Coupes du monde 2006 et 2010.'],
            ],
            'bibliography' => [
                ['title' => 'Arthur Boka', 'publisher' => 'Wikipédia en français', 'year' => null, 'url' => 'https://fr.wikipedia.org/wiki/Arthur_Boka'],
