            'summary' => 'Défenseur international ivoirien (1985-2024), Sol Bamba a joué au PSG, à Leicester et à Cardiff, et fut membre de l’équipe-type de Championship 2018.',
            'blocks' => [
                ['p', 'Souleymane Bamba, dit Sol Bamba, né le 13 janvier 1985 à Ivry-sur-Seine et mort le 31 août 2024 à Adana, en Turquie, est un footballeur international ivoirien qui a joué au poste de défenseur de 2004 à 2022. Passé par le centre de formation du Paris SG, il est international ivoirien chez les juniors, les moins de 20 ans et les olympiques. Il effectue ses débuts professionnels le 27 novembre 2004, à 19 ans, en remplaçant Stéphane Pichot lors d’un match de championnat face à Nice.'],
                ['h2', 'Leicester, Trabzonspor et Cardiff'],
                ['p', 'Il participe à la Coupe du monde des moins de 20 ans en 2003 et à la CAN junior en février 2005 avec la Côte d’Ivoire, puis honore sa première sélection avec les Éléphants le 19 novembre 2008, contre Israël. Il dispute la Coupe du monde 2010. Le 2 janvier 2011, il quitte l’Écosse pour Leicester City : six jours plus tard, pour son premier match, il marque sur corner après moins d’une minute de jeu en FA Cup. En juillet 2012, il signe cinq saisons à Trabzonspor. Avec Cardiff City, il est vice-champion de Championship en 2018 et membre de l’équipe-type de la division.'],
                ['h2', 'La maladie'],
                ['p', 'En mars 2021, il révèle son cancer dans les colonnes de L’Équipe magazine. Il meurt des suites de cette maladie le 31 août 2024, à Adana.'],
            ],
            'bibliography' => [
                ['title' => 'Sol Bamba', 'publisher' => 'Wikipédia en français', 'year' => null, 'url' => 'https://fr.wikipedia.org/wiki/Sol_Bamba'],
            ],
        ],
