                ['p', 'Ismaël Isaac, de son vrai nom Kaba Diakité Issiaka, est un chanteur de Côte d’Ivoire né en 1966 à Abidjan. Artiste reggae à la voix mélodieuse, il se distingue par un sens de l’harmonie vocale et une thématique « afro-optimiste ».'],
                ['h2', 'De Treichville aux studios'],
                ['p', 'Ses parents, venus de Ponodougou, s’installent à Treichville. Atteint de la polio à deux ans, il se consacre au chant et enregistre deux cassettes, Liberté et Tchilaba, en 1986, puis Yatiman en 1989.'],
                ['h2', 'Rahman et la reconnaissance'],
                ['p', 'Son premier CD, Rahman, produit en 1990 par Ibrahima Sylla, le fait connaître jusqu’en France, où Philippe Constantin le signe pour Island Records. Taxi Jump sort en 1993, suivi de Treich Feeling en 1997.'],
