                ['p', 'Fille aînée du percussionniste Boni Gnahoré, de la compagnie Ki Yi M’Bock d’Abidjan dirigée par Werewere Liking, elle quitte l’école à 12 ans pour rejoindre la compagnie, où elle apprend le théâtre, la danse, la musique et le chant.'],
