            'blocks' => [
                ['p', 'Sidiki Bakaba, né le 1er janvier 1949 en Côte d’Ivoire, est un acteur, réalisateur, cinéaste, metteur en scène et ambassadeur culturel franco-ivoirien.'],
                ['h2', 'Théâtre et cinéma'],
                ['p', 'Formé à l’École nationale d’art dramatique d’Abidjan, il enseigne ensuite l’expression corporelle à l’Institut national des arts. Il joue en Europe et en Afrique sous la direction de Patrice Chéreau, Claude Régy, Jean-Marie Serreau ou Sembène Ousmane.'],
                ['h2', 'Réalisateur et directeur'],
                ['p', 'Ses films Les Guérisseurs (1988) et La Voix de l’espoir sont primés, et Roues libres reçoit le prix du meilleur scénario au festival d’Amiens en 1998. Il dirige le Palais de la culture d’Abidjan, à Treichville, de 2000 à 2011, et y crée un Actor Studio. Il est le père du concepteur de jeux vidéo Dinga Bakaba.'],
            ],
