                ['p', 'Elle tourne dans plusieurs longs-métrages et films de télévision, et obtient deux prix d’interprétation féminine en 1994, l’un au festival Vues d’Afrique à Montréal, l’autre au festival de Kouriba au Maroc, pour son rôle dans Au nom du Christ de Roger Gnoan M’Bala. Dans Moolaadé de Sembène Ousmane, elle incarne la griotte, et elle tient le rôle principal de La Nuit de la vérité de Fanta Régina Nacro.'],
