                ['h2', 'Des maquis à la télévision'],
                ['p', 'Ancien joueur de football au FC Cosmos puis au Stade d’Abidjan, il obtient un BTS en gestion commerciale en 2003 et débute dans les maquis. Il passe ensuite à la radio de Koumassi, puis à Fréquence 2 auprès de Didier Bléou, et joue avec Digbeu Cravate dans Le grand jour.'],
