                ['h2', 'Du Jamel Comedy Club à l’Olympia'],
                ['p', 'En 2006, il participe à la première saison du Jamel Comedy Club. Il présente Le Patson Show en 2007, puis s’impose avec Yes we can Papa !!!, joué notamment à l’Olympia en 2011, avant Mon nom est Patson en 2013 et Docteur Patson, Rirothérapeute en 2018.'],
                ['h2', 'Un record et un engagement'],
                ['p', 'Le 5 novembre 2023, au théâtre Le République à Paris, il donne un spectacle de 6 heures et 16 minutes, battant le record officieux du plus long stand-up. Il a animé pendant près de quinze ans la tranche de 12 h à 13 h sur Africa no 1 et créé en 1998 l’association Micro d’Or.'],
