            'summary' => 'Artiste peintre ivoirien né le 21 octobre 1983, Aboudia vit entre Brooklyn et Abidjan et bénéficie d’une visibilité internationale à partir de 2011.',
            'blocks' => [
                ['p', 'Aboudia, de son vrai nom Abdoulaye Diarrassouba, est un artiste peintre ivoirien né le 21 octobre 1983 à Abengourou. Il vit et travaille entre Brooklyn et Abidjan.'],
                ['h2', 'La guerre comme matière'],
                ['p', 'Formé au Centre des arts appliqués de Bingerville, diplômé en art mural en 2003, il bénéficie d’une visibilité internationale à partir de 2011 en représentant des scènes de la guerre civile ivoirienne et de la bataille d’Abidjan. Ses œuvres sont photographiées par Finbar O’Reilly pour Reuters et exposées à la galerie Jack Bell de Londres en 2011, puis à la galerie Cécile Fakhoury à Abidjan en 2012.'],
                ['h2', 'Les « Môgôs »'],
                ['p', 'Ses personnages récurrents, les « Môgôs » — « un ami fidèle de tous les jours » en nouchi — représentent une jeunesse livrée à elle-même. Il crée la Fondation Aboudia à Bingerville en 2018 et reçoit le 5 septembre 2023 le prix d’excellence pour le cinéma et les arts visuels de la présidence ivoirienne.'],
            ],
            'bibliography' => [
