            'summary' => 'Sculpteur ivoirien (1925-1978) né à Grand-Lahou, Christian Lattier a ouvert la voie de l’art ivoirien contemporain.',
            'blocks' => [
                ['p', 'Christian Lattier, né le 25 décembre 1925 à Grand-Lahou et mort en 1978, est un sculpteur et artiste-plasticien de Côte d’Ivoire.'],
                ['h2', 'Formation française'],
                ['p', 'Après l’école primaire chez les Pères maristes de Saint-Chamond, il intègre l’École des beaux-arts de Saint-Étienne, où il obtient des premiers prix en deux ans, puis l’École des beaux-arts de Paris avec les sculpteurs Paul Niclausse et Georges Saupique. Il y apprend le modelage, l’architecture et la sculpture.'],
                ['h2', 'Le maître de la sculpture ivoirienne'],
                ['p', 'De retour en Côte d’Ivoire en 1962, il enseigne la sculpture à l’École nationale supérieure des beaux-arts d’Abidjan. En 1966, au premier Festival des arts nègres de Dakar, il obtient un grand prix et André Malraux le proclame « hors concours toutes disciplines ». Une salle du Palais de la culture d’Abidjan porte son nom.'],
            ],
            'bibliography' => [
                ['title' => 'Christian Lattier', 'publisher' => 'Wikipédia en français', 'year' => null, 'url' => 'https://fr.wikipedia.org/wiki/Christian_Lattier'],
