            'occupations' => ['Artiste', 'Designer'],
            'summary' => 'Artiste et designer ivoirienne (1967-2023), Valérie Oka a enseigné à l’INSAAC et exposé sur plusieurs continents.',
            'blocks' => [
                ['p', 'Valérie Oka, née le 22 janvier 1967 à Abidjan et morte le 8 avril 2023 à Assinie, est une artiste et designer ivoirienne. Née d’une mère française et d’un père ivoirien, elle part en France à l’âge de 8 ans et est diplômée de l’École supérieure d’arts graphiques de Paris en 1990.'],
                ['h2', 'Design et enseignement'],
                ['p', 'Elle travaille à Paris jusqu’en 1995, puis revient en Afrique comme designer, consultante en communication et professeure d’art contemporain à l’Institut national supérieur des arts et de l’action culturelle.'],
                ['h2', 'Une artiste multimédia'],
                ['p', 'Son travail mêle performances, installations, dessins, peintures, sculptures et mobilier, autour de l’intimité, du désir, de la violence et de la communication. Elle reçoit le prix de l’Union européenne à la Biennale de Dakar en 2000 et le grand prix de la Fondation Yehe en 2003.'],
