                ['h2', 'Le bois brûlé'],
                ['p', 'Formé à l’INSAAC à partir de 1988, diplômé national des beaux-arts en 1992 puis diplômé supérieur en 1994, il est boursier du DAAD en 1997 et poursuit à l’académie des beaux-arts de Düsseldorf. Il a pour matériau de prédilection la ciselure de bois brûlé.'],
