                ['p', 'Il découvre la programmation au lycée Blaise-Pascal d’Abidjan, puis part au Royaume-Uni en 2003 étudier le génie logiciel à l’université de Westminster. Il obtient son diplôme en informatique en 2007 et rentre en Côte d’Ivoire, où il se consacre à la photographie.'],
