                ['p', 'Aboua Kouakou, né le 20 mars 1965 à Kirifi, dans la région d’Abengourou, est un graveur et peintre ivoirien.'],
                ['h2', 'Beaux-arts et pédagogie'],
                ['p', 'Il suit une formation artistique à l’École des beaux-arts d’Abidjan, où il obtient un diplôme national en gravure en 1990. Il complète ensuite sa formation par une maîtrise en arts plastiques, une licence en socio-anthropologie et un master à la chaire UNESCO pour la culture de la paix. Il commence une carrière d’enseignant en 1994.'],
                ['h2', 'Gravure en couleurs'],
