            'blocks' => [
                ['p', 'Claudie Titty Dimbeng, dite Dimbeng, est une artiste plasticienne ivoirienne née en 1968 à Abidjan, qui vit à Paris.'],
                ['h2', 'Le « Mixed Art Relief »'],
                ['p', 'Elle est à l’origine du Mixed Art Relief, une technique mixte où la matière, les formes et les couleurs fusionnent grâce au sfumato de la Renaissance, ce qui met l’œuvre en relief, qu’elle soit abstraite ou figurative.'],
                ['h2', 'Une artiste internationale'],
                ['p', 'Après une première exposition publique en 2002 à la galerie Lorizon, à Paris, ses œuvres sont exposées en Afrique, aux Émirats arabes unis et en Europe, notamment au musée du Quai Branly en 2011 et au siège de l’UNESCO en 2012, où elle représente la Côte d’Ivoire.'],
