            'deathPlace' => null,
            'occupations' => ['Artiste peintre'],
            'summary' => 'Peintre ivoirien né en 1949 à Tabou, Youssouf Bath est l’une des figures principales du Vohou-vohou.',
            'blocks' => [
                ['p', 'Youssouf Bath, né à Tabou en 1949, dans la région du Bas-Sassandra, est un peintre ivoirien. Il est l’une des figures principales du Vohou-vohou, un collectif d’artistes ivoiriens qui a donné une impulsion importante à la créativité locale en exploitant des matériaux naturels ou de récupération.'],
                ['h2', 'La naissance du Vohou-vohou'],
                ['p', 'Il étudie à l’école des beaux-arts d’Abidjan dans les années 1970, formé à la technique académique par des professeurs français, avant de rejoindre les beaux-arts de Paris. En 1972, le premier choc pétrolier prive l’école de financement : faute de matériel, les élèves créent leurs propres supports et ingrédients de peinture, recyclant des objets et des racines, peignant sur des écorces.'],
            ],
            'bibliography' => [
                ['title' => 'Youssouf Bath', 'publisher' => 'Wikipédia en français', 'year' => null, 'url' => 'https://fr.wikipedia.org/wiki/Youssouf_Bath'],
