        [
            'slug' => 'jacques-samir-stenka',
            'name' => 'Jacques Samir Stenka',
            'fullName' => 'Jacques Samir Stenka',
            'birth' => '1945',
            'birthPlace' => 'Bingerville',
            'death' => '2024',
            'deathPlace' => 'Abidjan',
            'occupations' => ['Artiste peintre'],
            'summary' => 'Peintre ivoirien (1945-2024) né à Bingerville, Jacques Samir Stenka a construit une œuvre nourrie de symbolique attié.',
            'blocks' => [
                ['p', 'Jacques Samir Stenka, né le 3 novembre 1945 à Bingerville et mort le 24 novembre 2024 à Abidjan, est un peintre ivoirien. Il passe par l’orphelinat de Bingerville durant son enfance, expérience qui marque le début de son expression par les arts.'],
                ['h2', 'Formation et fidélité africaine'],
                ['p', 'Il obtient le diplôme supérieur des arts plastiques à l’École des beaux-arts de Paris et travaille dans l’atelier du peintre Jacques Yankel. Ce passage par l’école occidentale ne formate pas sa pensée : ses œuvres restent profondément africaines, ancrées dans une symbolique qu’il rattache à la mystique akié (attié) et à celle de l’Égypte ancienne.'],
                ['h2', 'Trois périodes'],
                ['p', 'Il décrit lui-même trois périodes : de 1974 à 1983, la période insecte, marquée par son métier de graphiste scientifique en biologie ; de 1984 à 1990, les hommes-insectes ; puis, de 1990 à 1994, une sortie de ce monde des hommes-insectes.'],
            ],
            'bibliography' => [
                ['title' => 'Jacques Samir Stenka', 'publisher' => 'Wikipédia en français', 'year' => null, 'url' => 'https://fr.wikipedia.org/wiki/Jacques_Samir_Stenka'],
            ],
