            'summary' => 'Peintre ivoirienne née le 2 mars 1958 à Grand-Bassam, Mathilde Moreau a dirigé l’École nationale des beaux-arts.',
            'blocks' => [
                ['p', 'Mathilde Moreau, épouse Kouassi, est une artiste peintre ivoirienne née le 2 mars 1958 à Grand-Bassam, au quartier Impérial. Ancienne étudiante de l’école des beaux-arts d’Abidjan, elle est l’un des précurseurs du mouvement Vohou-vohou.'],
                ['h2', 'Peintre et pédagogue'],
                ['p', 'Professeure certifiée en arts plastiques, spécialité peinture, elle est directrice de l’École nationale des beaux-arts de mars 2006 à octobre 2023.'],
                ['h2', 'Trente ans de peinture'],
                ['p', 'Son engagement pour l’affirmation des arts plastiques ivoiriens et africains lui vaut d’être présentée comme le plus grand peintre féminin de Côte d’Ivoire et l’un des grands noms de la peinture ivoirienne. En novembre 2017, elle a célébré ses trente ans de carrière artistique.'],
