            'summary' => 'Peintre ivoirien (1935-2021), Michel Kodjo est le premier peintre du pays à avoir présenté une exposition individuelle à Abidjan, en 1957.',
            'blocks' => [
                ['p', 'Michel Kodjo, né en 1935 à Soumier-Bia, dans la préfecture d’Aboisso, est le plus ancien des artistes peintres réputés de Côte d’Ivoire. Fils de Kodjo Kacou, planteur de la région d’Aboisso, il est apparenté à Amon Adingra, roi du Sanwi de l’époque.'],
                ['h2', 'Une première exposition en 1957'],
                ['p', 'Il est le premier peintre ivoirien à avoir présenté une exposition individuelle à Abidjan avant l’indépendance du pays, en 1957, à l’Hôtel de ville. Après cette exposition, il bénéficie d’une bourse d’études qui lui permet de suivre les cours de l’École des arts décoratifs de Nice de 1959 à 1961, puis ceux de l’École des beaux-arts de Clermont-Ferrand. Il obtient le premier prix de dessin et de décoration de la ville de Nice en 1964.'],
                ['h2', 'Une vie de peinture'],
                ['p', 'Formé d’abord à l’École de menuiserie de Treichville de 1950 à 1952, il s’intéresse ensuite à la peinture et travaille au Service de l’information en 1954. Il est mort dans la nuit du 23 au 24 mars 2021, à son domicile de Grand-Bassam, des suites d’un malaise.'],
            ],
